#!/usr/bin/env node
'use strict';

const path = require('node:path');
const moduleCache = new Map();
const moduleSources = {
  "git/locator.js": "const fs = require('node:fs');\nconst path = require('node:path');\n\n/**\n * Locate the .git directory for a given repository path.\n *\n * Handles:\n * - Standard repos: <path>/.git/ is a directory\n * - Worktrees: <path>/.git is a file containing \"gitdir: <actual-path>\"\n * - Bare repos: <path> itself contains HEAD, objects/, refs/\n * - Missing/invalid: throws with a clean message\n *\n * @param {string} repoPath — path to the repository root (or bare repo)\n * @returns {{ gitDir: string, isBare: boolean }} — absolute path to the git directory\n */\nfunction locateGitDir(repoPath) {\n  const absPath = path.resolve(repoPath);\n\n  if (!fs.existsSync(absPath)) {\n    throw new GitXRayError(`Path does not exist: ${absPath}`);\n  }\n\n  const dotGitPath = path.join(absPath, '.git');\n\n  // Case 1: .git is a directory (standard repo)\n  if (fs.existsSync(dotGitPath)) {\n    const stat = fs.statSync(dotGitPath);\n\n    if (stat.isDirectory()) {\n      validateGitDir(dotGitPath);\n      return { gitDir: dotGitPath, isBare: false };\n    }\n\n    // Case 2: .git is a file (worktree or submodule)\n    if (stat.isFile()) {\n      const content = fs.readFileSync(dotGitPath, 'utf8').trim();\n      const match = content.match(/^gitdir:\\s*(.+)$/);\n      if (!match) {\n        throw new GitXRayError(\n          `.git file exists but has unexpected format: ${dotGitPath}`\n        );\n      }\n      const resolvedGitDir = path.resolve(absPath, match[1]);\n      if (!fs.existsSync(resolvedGitDir)) {\n        throw new GitXRayError(\n          `.git file points to non-existent directory: ${resolvedGitDir}`\n        );\n      }\n      validateGitDir(resolvedGitDir);\n      return { gitDir: resolvedGitDir, isBare: false };\n    }\n  }\n\n  // Case 3: bare repo — the path itself is the git dir\n  if (isBareRepo(absPath)) {\n    return { gitDir: absPath, isBare: true };\n  }\n\n  throw new GitXRayError(\n    `Not a git repository (or any parent up to filesystem root): ${absPath}`\n  );\n}\n\n/**\n * Validate that a git directory has the minimum required structure.\n * @param {string} gitDir\n */\nfunction validateGitDir(gitDir) {\n  const headPath = path.join(gitDir, 'HEAD');\n  if (!fs.existsSync(headPath)) {\n    throw new GitXRayError(\n      `Invalid git directory (missing HEAD): ${gitDir}`\n    );\n  }\n\n  const objectsPath = path.join(gitDir, 'objects');\n  if (!fs.existsSync(objectsPath)) {\n    throw new GitXRayError(\n      `Invalid git directory (missing objects/): ${gitDir}`\n    );\n  }\n}\n\n/**\n * Check if a directory looks like a bare git repo.\n * Bare repos have HEAD, objects/, and refs/ at the top level (no .git subdir).\n * @param {string} dirPath\n * @returns {boolean}\n */\nfunction isBareRepo(dirPath) {\n  return (\n    fs.existsSync(path.join(dirPath, 'HEAD')) &&\n    fs.existsSync(path.join(dirPath, 'objects')) &&\n    fs.existsSync(path.join(dirPath, 'refs'))\n  );\n}\n\n/**\n * Custom error class for Git X-Ray user-facing errors.\n * These produce clean messages without stack traces.\n */\nclass GitXRayError extends Error {\n  constructor(message) {\n    super(message);\n    this.name = 'GitXRayError';\n  }\n}\n\nmodule.exports = { locateGitDir, GitXRayError };\n",
  "git/objects.js": "const fs = require('node:fs');\r\nconst path = require('node:path');\r\nconst zlib = require('node:zlib');\r\nconst crypto = require('node:crypto');\r\nconst { GitXRayError } = require('./locator.js');\r\nconst { readPackedObject, clearPackCache } = require('./pack.js');\r\n\r\n/**\r\n * Convert a hex SHA-1 hash to its loose object file path.\r\n * @param {string} gitDir — path to the .git directory\r\n * @param {string} hash — 40-char hex SHA-1\r\n * @returns {string} — absolute path to the loose object file\r\n */\r\nfunction hashToPath(gitDir, hash) {\r\n  return path.join(gitDir, 'objects', hash.slice(0, 2), hash.slice(2));\r\n}\r\n\r\n/**\r\n * Check if a loose object exists for the given hash.\r\n * @param {string} gitDir\r\n * @param {string} hash\r\n * @returns {boolean}\r\n */\r\nfunction looseObjectExists(gitDir, hash) {\r\n  return fs.existsSync(hashToPath(gitDir, hash));\r\n}\r\n\r\n/**\r\n * Read and inflate a loose git object from disk.\r\n *\r\n * Loose object format (after zlib inflate):\r\n *   <type> <size>\\0<content>\r\n *\r\n * @param {string} gitDir\r\n * @param {string} hash — 40-char hex SHA-1\r\n * @returns {{ type: string, size: number, body: Buffer }}\r\n */\r\nfunction readLooseObject(gitDir, hash) {\r\n  const objPath = hashToPath(gitDir, hash);\r\n\r\n  if (!fs.existsSync(objPath)) {\r\n    return null; // Object not found as loose — likely packed\r\n  }\r\n\r\n  let raw;\r\n  try {\r\n    const compressed = fs.readFileSync(objPath);\r\n    raw = zlib.inflateSync(compressed);\r\n  } catch (err) {\r\n    throw new GitXRayError(\r\n      `Failed to read/inflate object ${hash}: ${err.message}`\r\n    );\r\n  }\r\n\r\n  // Verify SHA-1 integrity\r\n  const actualHash = crypto.createHash('sha1').update(raw).digest('hex');\r\n  if (actualHash !== hash) {\r\n    throw new GitXRayError(\r\n      `Object ${hash} failed integrity check (computed ${actualHash})`\r\n    );\r\n  }\r\n\r\n  // Parse header: \"<type> <size>\\0\"\r\n  const nullIdx = raw.indexOf(0);\r\n  if (nullIdx === -1) {\r\n    throw new GitXRayError(`Malformed object ${hash}: missing null byte`);\r\n  }\r\n\r\n  const header = raw.subarray(0, nullIdx).toString('utf8');\r\n  const spaceIdx = header.indexOf(' ');\r\n  if (spaceIdx === -1) {\r\n    throw new GitXRayError(`Malformed object header in ${hash}: \"${header}\"`);\r\n  }\r\n\r\n  const type = header.slice(0, spaceIdx);\r\n  const size = parseInt(header.slice(spaceIdx + 1), 10);\r\n  const body = raw.subarray(nullIdx + 1);\r\n\r\n  if (body.length !== size) {\r\n    throw new GitXRayError(\r\n      `Object ${hash} size mismatch: header says ${size}, body is ${body.length}`\r\n    );\r\n  }\r\n\r\n  return { type, size, body };\r\n}\r\n\r\n/**\r\n * Parse a commit object body into structured data.\r\n *\r\n * Commit format (text, after the header):\r\n *   tree <tree-sha>\\n\r\n *   parent <parent-sha>\\n        (zero or more)\r\n *   author <name> <email> <ts> <tz>\\n\r\n *   committer <name> <email> <ts> <tz>\\n\r\n *   [gpgsig ...]\\n               (optional, skip)\r\n *   \\n\r\n *   <commit message>\r\n *\r\n * @param {string} hash — the commit's own hash\r\n * @param {Buffer} body — raw commit body (after type/size header)\r\n * @returns {ParsedCommit}\r\n */\r\nfunction parseCommit(hash, body) {\r\n  // Decode as UTF-8 with latin1 fallback\r\n  let text;\r\n  try {\r\n    text = body.toString('utf8');\r\n  } catch {\r\n    text = body.toString('latin1');\r\n  }\r\n\r\n  const result = {\r\n    hash,\r\n    tree: null,\r\n    parents: [],\r\n    author: null,\r\n    committer: null,\r\n    message: '',\r\n  };\r\n\r\n  // Split header block from message at the first blank line\r\n  const blankLineIdx = text.indexOf('\\n\\n');\r\n\r\n  let headerBlock, messageBlock;\r\n  if (blankLineIdx === -1) {\r\n    // Edge case: commit with no message\r\n    headerBlock = text;\r\n    messageBlock = '';\r\n  } else {\r\n    headerBlock = text.slice(0, blankLineIdx);\r\n    messageBlock = text.slice(blankLineIdx + 2);\r\n  }\r\n\r\n  result.message = messageBlock.trimEnd();\r\n\r\n  // Parse header lines, handling multi-line fields (gpgsig)\r\n  const lines = headerBlock.split('\\n');\r\n  let i = 0;\r\n  while (i < lines.length) {\r\n    const line = lines[i];\r\n\r\n    if (line.startsWith('tree ')) {\r\n      result.tree = line.slice(5).trim();\r\n    } else if (line.startsWith('parent ')) {\r\n      result.parents.push(line.slice(7).trim());\r\n    } else if (line.startsWith('author ')) {\r\n      result.author = parseAuthorLine(line.slice(7));\r\n    } else if (line.startsWith('committer ')) {\r\n      result.committer = parseAuthorLine(line.slice(10));\r\n    } else if (line.startsWith('gpgsig ') || line.startsWith('mergetag ')) {\r\n      // Skip multi-line PGP signature / mergetag — continues while next line starts with space\r\n      i++;\r\n      while (i < lines.length && lines[i].startsWith(' ')) {\r\n        i++;\r\n      }\r\n      continue; // Don't increment i again\r\n    }\r\n    // Ignore unknown header fields silently (encoding, etc.)\r\n    i++;\r\n  }\r\n\r\n  if (!result.tree) {\r\n    throw new GitXRayError(`Commit ${hash} missing tree field`);\r\n  }\r\n\r\n  return result;\r\n}\r\n\r\n/**\r\n * Parse an author/committer line.\r\n * Format: \"Name <email> timestamp timezone\"\r\n * Example: \"Alice <alice@example.com> 1625000000 +0530\"\r\n *\r\n * @param {string} line\r\n * @returns {{ name: string, email: string, timestamp: number, tz: string }}\r\n */\r\nfunction parseAuthorLine(line) {\r\n  // Match: everything up to < as name, then email in <>, then timestamp and tz\r\n  const match = line.match(/^(.+?)\\s*<([^>]*)>\\s*(\\d+)\\s*([+-]\\d{4})$/);\r\n  if (!match) {\r\n    // Fallback for malformed author lines\r\n    return { name: line.trim(), email: '', timestamp: 0, tz: '+0000' };\r\n  }\r\n\r\n  return {\r\n    name: match[1].trim(),\r\n    email: match[2],\r\n    timestamp: parseInt(match[3], 10),\r\n    tz: match[4],\r\n  };\r\n}\r\n\r\n/**\r\n * Parse a tree object body into an array of entries.\r\n *\r\n * Tree object binary format (repeated, NO delimiters between entries):\r\n *   <mode> <name>\\0<20-byte-sha1>\r\n *\r\n * Where:\r\n * - mode is ASCII digits (e.g., \"100644\", \"40000\")\r\n * - name is the filename (UTF-8)\r\n * - The null byte terminates the name\r\n * - Immediately followed by 20 raw bytes of SHA-1 (NOT hex-encoded)\r\n *\r\n * @param {Buffer} body — raw tree body (after type/size header)\r\n * @returns {TreeEntry[]}\r\n */\r\nfunction parseTree(body) {\r\n  const entries = [];\r\n  let offset = 0;\r\n\r\n  while (offset < body.length) {\r\n    // Find the space between mode and name\r\n    const spaceIdx = body.indexOf(0x20, offset); // ASCII space\r\n    if (spaceIdx === -1) {\r\n      break; // Malformed, stop\r\n    }\r\n    const mode = body.subarray(offset, spaceIdx).toString('ascii');\r\n\r\n    // Find the null byte after the name\r\n    const nullIdx = body.indexOf(0x00, spaceIdx + 1);\r\n    if (nullIdx === -1) {\r\n      break; // Malformed, stop\r\n    }\r\n    const name = body.subarray(spaceIdx + 1, nullIdx).toString('utf8');\r\n\r\n    // Read 20 raw bytes of SHA-1 hash\r\n    const hashStart = nullIdx + 1;\r\n    const hashEnd = hashStart + 20;\r\n    if (hashEnd > body.length) {\r\n      break; // Truncated\r\n    }\r\n    const hash = body.subarray(hashStart, hashEnd).toString('hex');\r\n\r\n    entries.push({ mode, name, hash });\r\n    offset = hashEnd;\r\n  }\r\n\r\n  return entries;\r\n}\r\n\r\n/**\r\n * Storage-agnostic object reader.\r\n * Tries to read the object as a loose object first. If not found,\r\n * searches all packfiles via IDX lookup.\r\n *\r\n * This is the primary API that the rest of Git X-Ray should use\r\n * for generic object access. readLooseObject() remains available\r\n * for callers that specifically need loose-only semantics.\r\n *\r\n * @param {string} gitDir — path to the .git directory\r\n * @param {string} hash — 40-char hex SHA-1\r\n * @param {number} [_depth] — internal: current delta chain depth (for REF_DELTA recursion)\r\n * @returns {{ type: string, size: number, body: Buffer } | null}\r\n */\r\nfunction readObject(gitDir, hash, _depth) {\r\n  // 1. Try loose object first (fast path)\r\n  const loose = readLooseObject(gitDir, hash);\r\n  if (loose) return loose;\r\n\r\n  // 2. Try packed objects — pass readObject itself as the REF_DELTA resolver\r\n  // so that REF_DELTA bases can be resolved from any storage location\r\n  return readPackedObject(gitDir, hash, readObject, _depth || 0);\r\n}\r\n\r\nmodule.exports = {\r\n  hashToPath,\r\n  looseObjectExists,\r\n  readLooseObject,\r\n  readObject,\r\n  parseCommit,\r\n  parseTree,\r\n  clearPackCache,\r\n};\r\n",
  "git/refs.js": "const fs = require('node:fs');\nconst path = require('node:path');\nconst { GitXRayError } = require('./locator.js');\n\n/**\n * Read HEAD and resolve it to a commit SHA-1.\n *\n * HEAD can be:\n * 1. A symbolic ref: \"ref: refs/heads/main\\n\" → follow the ref\n * 2. A detached HEAD: \"abc123...\\n\" → direct SHA-1\n *\n * @param {string} gitDir — path to the .git directory\n * @returns {{ hash: string, ref: string|null }} — commit hash + ref name (null if detached)\n */\nfunction resolveHead(gitDir) {\n  const headPath = path.join(gitDir, 'HEAD');\n\n  if (!fs.existsSync(headPath)) {\n    throw new GitXRayError(`HEAD file not found: ${headPath}`);\n  }\n\n  const content = fs.readFileSync(headPath, 'utf8').trim();\n\n  // Case 1: symbolic ref\n  if (content.startsWith('ref: ')) {\n    const refName = content.slice(5).trim();\n    const hash = resolveRef(gitDir, refName);\n    if (!hash) {\n      throw new GitXRayError(\n        `HEAD points to ${refName} which cannot be resolved (empty repo or broken ref)`\n      );\n    }\n    return { hash, ref: refName };\n  }\n\n  // Case 2: detached HEAD (direct hash)\n  if (/^[0-9a-f]{40}$/i.test(content)) {\n    return { hash: content.toLowerCase(), ref: null };\n  }\n\n  throw new GitXRayError(`Unexpected HEAD format: \"${content}\"`);\n}\n\n/**\n * Resolve a ref name (e.g., \"refs/heads/main\") to a SHA-1 hash.\n * Checks loose ref files first, then falls back to packed-refs.\n *\n * @param {string} gitDir\n * @param {string} refName — e.g., \"refs/heads/main\"\n * @returns {string|null} — 40-char hex SHA-1, or null if unresolvable\n */\nfunction resolveRef(gitDir, refName) {\n  // Try loose ref first\n  const refPath = path.join(gitDir, refName);\n  if (fs.existsSync(refPath)) {\n    const content = fs.readFileSync(refPath, 'utf8').trim();\n    if (/^[0-9a-f]{40}$/i.test(content)) {\n      return content.toLowerCase();\n    }\n    // Could be another symbolic ref (rare but possible)\n    if (content.startsWith('ref: ')) {\n      return resolveRef(gitDir, content.slice(5).trim());\n    }\n  }\n\n  // Try packed-refs\n  return resolveFromPackedRefs(gitDir, refName);\n}\n\n/**\n * Look up a ref in the packed-refs file.\n *\n * packed-refs format:\n *   # comment lines\n *   <sha1> <refname>\n *   ^<sha1>           (peel line — points to the dereferenced object for tags)\n *\n * @param {string} gitDir\n * @param {string} refName\n * @returns {string|null}\n */\nfunction resolveFromPackedRefs(gitDir, refName) {\n  const packedRefsPath = path.join(gitDir, 'packed-refs');\n  if (!fs.existsSync(packedRefsPath)) {\n    return null;\n  }\n\n  const content = fs.readFileSync(packedRefsPath, 'utf8');\n  const lines = content.split('\\n');\n\n  for (const line of lines) {\n    // Skip comments and peel lines\n    if (line.startsWith('#') || line.startsWith('^') || line.trim() === '') {\n      continue;\n    }\n\n    const parts = line.trim().split(/\\s+/);\n    if (parts.length >= 2 && parts[1] === refName) {\n      return parts[0].toLowerCase();\n    }\n  }\n\n  return null;\n}\n\n/**\n * Get all branch tips (refs/heads/*) as { name, hash } pairs.\n * Reads from both loose refs and packed-refs.\n *\n * @param {string} gitDir\n * @returns {{ name: string, hash: string }[]}\n */\nfunction getAllBranches(gitDir) {\n  const branches = new Map(); // refName → hash (Map deduplicates loose vs packed)\n\n  // 1. Read loose refs from refs/heads/\n  const headsDir = path.join(gitDir, 'refs', 'heads');\n  if (fs.existsSync(headsDir)) {\n    walkRefsDir(headsDir, 'refs/heads', branches);\n  }\n\n  // 2. Read packed-refs for any branches not already found\n  const packedRefsPath = path.join(gitDir, 'packed-refs');\n  if (fs.existsSync(packedRefsPath)) {\n    const content = fs.readFileSync(packedRefsPath, 'utf8');\n    for (const line of content.split('\\n')) {\n      if (line.startsWith('#') || line.startsWith('^') || line.trim() === '') {\n        continue;\n      }\n      const parts = line.trim().split(/\\s+/);\n      if (parts.length >= 2 && parts[1].startsWith('refs/heads/')) {\n        // Loose refs take precedence — only add if not already present\n        if (!branches.has(parts[1])) {\n          branches.set(parts[1], parts[0].toLowerCase());\n        }\n      }\n    }\n  }\n\n  return Array.from(branches.entries()).map(([name, hash]) => ({\n    name: name.replace('refs/heads/', ''),\n    hash,\n  }));\n}\n\n/**\n * Recursively walk a refs directory to collect all refs.\n * @param {string} dirPath — absolute path to the directory\n * @param {string} prefix — ref prefix (e.g., \"refs/heads\")\n * @param {Map<string, string>} result — accumulated results\n */\nfunction walkRefsDir(dirPath, prefix, result) {\n  let entries;\n  try {\n    entries = fs.readdirSync(dirPath, { withFileTypes: true });\n  } catch {\n    return;\n  }\n\n  for (const entry of entries) {\n    const fullPath = path.join(dirPath, entry.name);\n    const refName = `${prefix}/${entry.name}`;\n\n    if (entry.isDirectory()) {\n      walkRefsDir(fullPath, refName, result);\n    } else if (entry.isFile()) {\n      try {\n        const hash = fs.readFileSync(fullPath, 'utf8').trim();\n        if (/^[0-9a-f]{40}$/i.test(hash)) {\n          result.set(refName, hash.toLowerCase());\n        }\n      } catch {\n        // Skip unreadable ref files\n      }\n    }\n  }\n}\n\nmodule.exports = { resolveHead, resolveRef, getAllBranches };\n",
  "git/pack.js": "const fs = require('node:fs');\r\nconst path = require('node:path');\r\nconst zlib = require('node:zlib');\r\nconst { GitXRayError } = require('./locator.js');\r\n\r\n// ─── Constants ────────────────────────────────────────────────────────────────\r\n\r\n// IDX v2 magic bytes: 0xff 0x74 0x4f 0x63 (first 4 bytes)\r\nconst IDX_V2_MAGIC = Buffer.from([0xff, 0x74, 0x4f, 0x63]);\r\n\r\n// PACK file magic bytes: 'PACK' (ASCII)\r\nconst PACK_MAGIC = Buffer.from('PACK', 'ascii');\r\n\r\n// Git pack object type codes\r\nconst OBJ_COMMIT  = 1;\r\nconst OBJ_TREE    = 2;\r\nconst OBJ_BLOB    = 3;\r\nconst OBJ_TAG     = 4;\r\nconst OBJ_OFS_DELTA = 6;\r\nconst OBJ_REF_DELTA = 7;\r\n\r\n// Map type code → type string\r\nconst TYPE_NAMES = {\r\n  [OBJ_COMMIT]: 'commit',\r\n  [OBJ_TREE]:   'tree',\r\n  [OBJ_BLOB]:   'blob',\r\n  [OBJ_TAG]:    'tag',\r\n};\r\n\r\n// Maximum delta chain depth to prevent infinite recursion\r\nconst MAX_DELTA_DEPTH = 50;\r\n\r\n// ─── Pack Discovery ───────────────────────────────────────────────────────────\r\n\r\n/**\r\n * Discover all packfile/index pairs in a git directory.\r\n * Scans .git/objects/pack/ for matching .pack + .idx files.\r\n *\r\n * @param {string} gitDir — path to the .git directory\r\n * @returns {{ idxPath: string, packPath: string }[]}\r\n */\r\nfunction discoverPackFiles(gitDir) {\r\n  const packDir = path.join(gitDir, 'objects', 'pack');\r\n\r\n  if (!fs.existsSync(packDir)) {\r\n    return [];\r\n  }\r\n\r\n  let entries;\r\n  try {\r\n    entries = fs.readdirSync(packDir);\r\n  } catch {\r\n    return [];\r\n  }\r\n\r\n  // Collect all .pack files, then verify matching .idx exists\r\n  const packs = [];\r\n  for (const entry of entries) {\r\n    if (!entry.endsWith('.pack')) continue;\r\n\r\n    const baseName = entry.slice(0, -5); // strip '.pack'\r\n    const idxName = baseName + '.idx';\r\n\r\n    const packPath = path.join(packDir, entry);\r\n    const idxPath = path.join(packDir, idxName);\r\n\r\n    if (fs.existsSync(idxPath)) {\r\n      packs.push({ idxPath, packPath });\r\n    }\r\n    // If .idx is missing, skip silently — we can't efficiently look up objects\r\n  }\r\n\r\n  return packs;\r\n}\r\n\r\n// ─── IDX v2 Parser ────────────────────────────────────────────────────────────\r\n\r\n/**\r\n * Parse a Git IDX v2 file into a lookup structure.\r\n *\r\n * IDX v2 layout:\r\n *   [0..3]     Magic: ff 74 4f 63\r\n *   [4..7]     Version: 00 00 00 02\r\n *   [8..1031]  Fanout table: 256 × 4-byte big-endian uint32\r\n *              fanout[i] = cumulative count of objects with first byte <= i\r\n *              fanout[255] = total object count\r\n *   [1032..]   SHA-1 table: N × 20 bytes (sorted)\r\n *   [..]       CRC32 table: N × 4 bytes (we skip this)\r\n *   [..]       Offset table: N × 4 bytes\r\n *              If MSB is set, the remaining 31 bits index into the large offset table\r\n *   [..]       Large offset table: M × 8 bytes (only if any offset > 2^31)\r\n *\r\n * @param {string} idxPath — path to the .idx file\r\n * @returns {ParsedIdx}\r\n */\r\nfunction parseIdx(idxPath) {\r\n  let buf;\r\n  try {\r\n    buf = fs.readFileSync(idxPath);\r\n  } catch (err) {\r\n    throw new GitXRayError(`Failed to read IDX file ${idxPath}: ${err.message}`);\r\n  }\r\n\r\n  // Validate minimum size: magic(4) + version(4) + fanout(1024) = 1032\r\n  if (buf.length < 1032) {\r\n    throw new GitXRayError(`IDX file too small: ${idxPath} (${buf.length} bytes)`);\r\n  }\r\n\r\n  // Validate magic\r\n  if (!buf.subarray(0, 4).equals(IDX_V2_MAGIC)) {\r\n    throw new GitXRayError(\r\n      `Unsupported IDX format in ${idxPath}: expected v2 magic (ff744f63), ` +\r\n      `got ${buf.subarray(0, 4).toString('hex')}`\r\n    );\r\n  }\r\n\r\n  // Validate version\r\n  const version = buf.readUInt32BE(4);\r\n  if (version !== 2) {\r\n    throw new GitXRayError(\r\n      `Unsupported IDX version ${version} in ${idxPath} (only v2 is supported)`\r\n    );\r\n  }\r\n\r\n  // Read fanout table (256 entries, 4 bytes each, at offset 8)\r\n  const fanout = new Uint32Array(256);\r\n  for (let i = 0; i < 256; i++) {\r\n    fanout[i] = buf.readUInt32BE(8 + i * 4);\r\n  }\r\n\r\n  const objectCount = fanout[255];\r\n\r\n  // Compute section offsets\r\n  const shaTableOffset = 1032;                                    // after fanout\r\n  const crc32TableOffset = shaTableOffset + objectCount * 20;     // after SHA-1s\r\n  const offsetTableOffset = crc32TableOffset + objectCount * 4;   // after CRC32s\r\n  const largeOffsetTableOffset = offsetTableOffset + objectCount * 4;\r\n\r\n  // Validate buffer size is large enough for all sections\r\n  const minSize = offsetTableOffset + objectCount * 4;\r\n  if (buf.length < minSize) {\r\n    throw new GitXRayError(\r\n      `IDX file ${idxPath} is truncated: expected at least ${minSize} bytes, got ${buf.length}`\r\n    );\r\n  }\r\n\r\n  return {\r\n    buffer: buf,\r\n    fanout,\r\n    objectCount,\r\n    shaTableOffset,\r\n    offsetTableOffset,\r\n    largeOffsetTableOffset,\r\n    idxPath,\r\n  };\r\n}\r\n\r\n/**\r\n * Look up a SHA-1 hash in a parsed IDX file.\r\n * Uses the fanout table to narrow the search range, then binary searches.\r\n *\r\n * @param {ParsedIdx} idx — parsed IDX data\r\n * @param {string} hash — 40-char hex SHA-1\r\n * @returns {number|null} — pack offset, or null if not found\r\n */\r\nfunction idxLookup(idx, hash) {\r\n  const hashBuf = Buffer.from(hash, 'hex');\r\n  const firstByte = hashBuf[0];\r\n\r\n  // Use fanout to get the range of entries with this first byte\r\n  const lo = firstByte === 0 ? 0 : idx.fanout[firstByte - 1];\r\n  const hi = idx.fanout[firstByte];\r\n\r\n  if (lo >= hi) {\r\n    return null; // No objects with this first byte\r\n  }\r\n\r\n  // Binary search within the SHA-1 table\r\n  let left = lo;\r\n  let right = hi - 1;\r\n\r\n  while (left <= right) {\r\n    const mid = (left + right) >>> 1;\r\n    const entrySha = idx.buffer.subarray(\r\n      idx.shaTableOffset + mid * 20,\r\n      idx.shaTableOffset + mid * 20 + 20\r\n    );\r\n\r\n    const cmp = Buffer.compare(hashBuf, entrySha);\r\n    if (cmp === 0) {\r\n      // Found — read the pack offset\r\n      return readPackOffset(idx, mid);\r\n    } else if (cmp < 0) {\r\n      right = mid - 1;\r\n    } else {\r\n      left = mid + 1;\r\n    }\r\n  }\r\n\r\n  return null; // Not found\r\n}\r\n\r\n/**\r\n * Read the pack offset for entry at index `entryIndex` from the IDX offset table.\r\n * Handles large offsets (MSB set → index into 8-byte large offset table).\r\n *\r\n * @param {ParsedIdx} idx\r\n * @param {number} entryIndex\r\n * @returns {number}\r\n */\r\nfunction readPackOffset(idx, entryIndex) {\r\n  const rawOffset = idx.buffer.readUInt32BE(\r\n    idx.offsetTableOffset + entryIndex * 4\r\n  );\r\n\r\n  // If MSB is set, the remaining 31 bits are an index into the large offset table\r\n  if (rawOffset & 0x80000000) {\r\n    const largeIdx = rawOffset & 0x7fffffff;\r\n    const largeOffset = idx.largeOffsetTableOffset + largeIdx * 8;\r\n\r\n    // Read 8-byte big-endian offset\r\n    // Node's readBigUInt64BE returns a BigInt; convert to Number\r\n    // (safe for offsets up to ~9 PB which is well beyond any real packfile)\r\n    const hi32 = idx.buffer.readUInt32BE(largeOffset);\r\n    const lo32 = idx.buffer.readUInt32BE(largeOffset + 4);\r\n    return hi32 * 0x100000000 + lo32;\r\n  }\r\n\r\n  return rawOffset;\r\n}\r\n\r\n// ─── Pack Object Reader ───────────────────────────────────────────────────────\r\n\r\n/**\r\n * Read and validate a PACK file header.\r\n *\r\n * PACK header layout:\r\n *   [0..3]   Magic: 'PACK' (ASCII)\r\n *   [4..7]   Version: 2 or 3 (big-endian uint32)\r\n *   [8..11]  Object count (big-endian uint32)\r\n *\r\n * @param {Buffer} buf — pack file buffer (at least first 12 bytes)\r\n * @param {string} packPath — for error messages\r\n * @returns {{ version: number, objectCount: number }}\r\n */\r\nfunction readPackHeader(buf, packPath) {\r\n  if (buf.length < 12) {\r\n    throw new GitXRayError(`PACK file too small: ${packPath} (${buf.length} bytes)`);\r\n  }\r\n\r\n  if (!buf.subarray(0, 4).equals(PACK_MAGIC)) {\r\n    throw new GitXRayError(\r\n      `Invalid PACK magic in ${packPath}: expected 'PACK', got '${buf.subarray(0, 4).toString('ascii')}'`\r\n    );\r\n  }\r\n\r\n  const version = buf.readUInt32BE(4);\r\n  if (version !== 2 && version !== 3) {\r\n    throw new GitXRayError(\r\n      `Unsupported PACK version ${version} in ${packPath} (only v2/v3 supported)`\r\n    );\r\n  }\r\n\r\n  const objectCount = buf.readUInt32BE(8);\r\n  return { version, objectCount };\r\n}\r\n\r\n/**\r\n * Read a pack object at a given offset within a pack buffer.\r\n *\r\n * Pack object header encoding (variable-length):\r\n *   First byte:  MSB = continuation bit\r\n *                bits 6..4 = object type (3 bits)\r\n *                bits 3..0 = size (low 4 bits)\r\n *   Subsequent bytes: MSB = continuation, bits 6..0 = size (next 7 bits each)\r\n *\r\n * After the header, the data is zlib-compressed (for normal objects).\r\n *\r\n * @param {Buffer} packBuf — entire pack file buffer\r\n * @param {number} offset — byte offset of this object within the pack\r\n * @param {string} packPath — for error messages\r\n * @param {Function} resolveBase — function(gitDir, hash) for REF_DELTA base resolution\r\n * @param {string} gitDir — for REF_DELTA base resolution\r\n * @param {Set} [visiting] — set of offsets currently being resolved (cycle detection)\r\n * @param {number} [depth] — current delta chain depth\r\n * @returns {{ type: string, size: number, body: Buffer }}\r\n */\r\nfunction readPackObject(packBuf, offset, packPath, resolveBase, gitDir, visiting, depth) {\r\n  if (!visiting) visiting = new Set();\r\n  if (!depth) depth = 0;\r\n\r\n  if (depth > MAX_DELTA_DEPTH) {\r\n    throw new GitXRayError(\r\n      `Delta chain too deep (>${MAX_DELTA_DEPTH}) at offset ${offset} in ${packPath}`\r\n    );\r\n  }\r\n\r\n  if (offset < 12 || offset >= packBuf.length) {\r\n    throw new GitXRayError(\r\n      `Invalid pack offset ${offset} in ${packPath} (file size: ${packBuf.length})`\r\n    );\r\n  }\r\n\r\n  // Parse the variable-length object header\r\n  let byte = packBuf[offset];\r\n  const objType = (byte >> 4) & 0x07;  // bits 6..4\r\n  let size = byte & 0x0f;              // bits 3..0\r\n  let shift = 4;\r\n  let pos = offset + 1;\r\n\r\n  while (byte & 0x80) {  // continuation bit\r\n    if (pos >= packBuf.length) {\r\n      throw new GitXRayError(\r\n        `Truncated object header at offset ${offset} in ${packPath}`\r\n      );\r\n    }\r\n    byte = packBuf[pos++];\r\n    size |= (byte & 0x7f) << shift;\r\n    shift += 7;\r\n  }\r\n\r\n  // Handle by object type\r\n  if (objType >= OBJ_COMMIT && objType <= OBJ_TAG) {\r\n    // Normal object — decompress zlib data\r\n    return readNormalPackObject(packBuf, pos, objType, size, offset, packPath);\r\n  }\r\n\r\n  if (objType === OBJ_OFS_DELTA) {\r\n    return readOfsDelta(packBuf, pos, offset, size, packPath, resolveBase, gitDir, visiting, depth);\r\n  }\r\n\r\n  if (objType === OBJ_REF_DELTA) {\r\n    return readRefDelta(packBuf, pos, offset, size, packPath, resolveBase, gitDir, visiting, depth);\r\n  }\r\n\r\n  throw new GitXRayError(\r\n    `Unknown pack object type ${objType} at offset ${offset} in ${packPath}`\r\n  );\r\n}\r\n\r\n/**\r\n * Read a normal (non-delta) packed object.\r\n * Decompresses the zlib data starting at `dataOffset`.\r\n *\r\n * @param {Buffer} packBuf\r\n * @param {number} dataOffset — start of zlib-compressed data\r\n * @param {number} objType — type code (1-4)\r\n * @param {number} expectedSize — declared size from header\r\n * @param {number} objOffset — original object offset (for error messages)\r\n * @param {string} packPath\r\n * @returns {{ type: string, size: number, body: Buffer }}\r\n */\r\nfunction readNormalPackObject(packBuf, dataOffset, objType, expectedSize, objOffset, packPath) {\r\n  const typeName = TYPE_NAMES[objType];\r\n  if (!typeName) {\r\n    throw new GitXRayError(\r\n      `Unknown normal object type ${objType} at offset ${objOffset} in ${packPath}`\r\n    );\r\n  }\r\n\r\n  let body;\r\n  try {\r\n    // Decompress from dataOffset to end of buffer — zlib will stop at the\r\n    // end of the compressed stream automatically\r\n    body = zlib.inflateSync(packBuf.subarray(dataOffset));\r\n  } catch (err) {\r\n    throw new GitXRayError(\r\n      `Failed to decompress pack object at offset ${objOffset} in ${packPath}: ${err.message}`\r\n    );\r\n  }\r\n\r\n  if (body.length !== expectedSize) {\r\n    throw new GitXRayError(\r\n      `Pack object size mismatch at offset ${objOffset} in ${packPath}: ` +\r\n      `header says ${expectedSize}, decompressed ${body.length}`\r\n    );\r\n  }\r\n\r\n  return { type: typeName, size: body.length, body };\r\n}\r\n\r\n// ─── Delta Support (stubs for Checkpoint 2, full impl in Checkpoint 3) ──────\r\n\r\n/**\r\n * Read an OFS_DELTA object. The delta identifies its base via a negative\r\n * offset from the current object's position in the pack.\r\n *\r\n * OFS_DELTA offset encoding (variable-length, after the object header):\r\n *   First byte: bits 6..0 = offset value (7 bits), MSB = continuation\r\n *   Subsequent bytes: each adds 7 more bits, but with +1 bias:\r\n *     offset = ((offset + 1) << 7) | (byte & 0x7f)\r\n *\r\n * After the offset, the remaining data is the zlib-compressed delta.\r\n */\r\nfunction readOfsDelta(packBuf, pos, objOffset, deltaSize, packPath, resolveBase, gitDir, visiting, depth) {\r\n  // Decode the variable-length negative offset\r\n  let byte = packBuf[pos++];\r\n  let baseOffset = byte & 0x7f;\r\n\r\n  while (byte & 0x80) {\r\n    if (pos >= packBuf.length) {\r\n      throw new GitXRayError(\r\n        `Truncated OFS_DELTA offset at offset ${objOffset} in ${packPath}`\r\n      );\r\n    }\r\n    byte = packBuf[pos++];\r\n    // The +1 bias is critical for Git's encoding\r\n    baseOffset = ((baseOffset + 1) << 7) | (byte & 0x7f);\r\n  }\r\n\r\n  const basePackOffset = objOffset - baseOffset;\r\n  if (basePackOffset < 12) {\r\n    throw new GitXRayError(\r\n      `OFS_DELTA at offset ${objOffset} points to invalid base offset ${basePackOffset} in ${packPath}`\r\n    );\r\n  }\r\n\r\n  // Cycle detection\r\n  if (visiting.has(basePackOffset)) {\r\n    throw new GitXRayError(\r\n      `Circular OFS_DELTA reference detected at offset ${objOffset} in ${packPath}`\r\n    );\r\n  }\r\n\r\n  visiting.add(objOffset);\r\n\r\n  // Recursively resolve the base object from the pack\r\n  const baseObj = readPackObject(packBuf, basePackOffset, packPath, resolveBase, gitDir, visiting, depth + 1);\r\n\r\n  // Decompress the delta instructions\r\n  let deltaData;\r\n  try {\r\n    deltaData = zlib.inflateSync(packBuf.subarray(pos));\r\n  } catch (err) {\r\n    throw new GitXRayError(\r\n      `Failed to decompress OFS_DELTA data at offset ${objOffset} in ${packPath}: ${err.message}`\r\n    );\r\n  }\r\n\r\n  // Apply delta to reconstruct the target object\r\n  const resultBody = applyDelta(baseObj.body, deltaData, objOffset, packPath);\r\n\r\n  return { type: baseObj.type, size: resultBody.length, body: resultBody };\r\n}\r\n\r\n/**\r\n * Read a REF_DELTA object. The delta identifies its base via a 20-byte SHA-1.\r\n * The base object may be anywhere (loose, in this pack, or in another pack).\r\n */\r\nfunction readRefDelta(packBuf, pos, objOffset, deltaSize, packPath, resolveBase, gitDir, visiting, depth) {\r\n  // Read the 20-byte base SHA-1\r\n  if (pos + 20 > packBuf.length) {\r\n    throw new GitXRayError(\r\n      `Truncated REF_DELTA base hash at offset ${objOffset} in ${packPath}`\r\n    );\r\n  }\r\n\r\n  const baseHash = packBuf.subarray(pos, pos + 20).toString('hex');\r\n  pos += 20;\r\n\r\n  // Resolve the base object via the general readObject path\r\n  if (!resolveBase) {\r\n    throw new GitXRayError(\r\n      `REF_DELTA at offset ${objOffset} in ${packPath} requires base ${baseHash} but no resolver provided`\r\n    );\r\n  }\r\n\r\n  const baseObj = resolveBase(gitDir, baseHash, depth + 1);\r\n  if (!baseObj) {\r\n    throw new GitXRayError(\r\n      `REF_DELTA at offset ${objOffset} in ${packPath}: base object ${baseHash} not found`\r\n    );\r\n  }\r\n\r\n  // Decompress the delta instructions\r\n  let deltaData;\r\n  try {\r\n    deltaData = zlib.inflateSync(packBuf.subarray(pos));\r\n  } catch (err) {\r\n    throw new GitXRayError(\r\n      `Failed to decompress REF_DELTA data at offset ${objOffset} in ${packPath}: ${err.message}`\r\n    );\r\n  }\r\n\r\n  // Apply delta\r\n  const resultBody = applyDelta(baseObj.body, deltaData, objOffset, packPath);\r\n\r\n  return { type: baseObj.type, size: resultBody.length, body: resultBody };\r\n}\r\n\r\n// ─── Delta Instruction Decoder ────────────────────────────────────────────────\r\n\r\n/**\r\n * Read a variable-length size from delta data.\r\n * Used for base size and result size at the start of delta instructions.\r\n *\r\n * Encoding: each byte contributes 7 bits; MSB = continuation.\r\n *\r\n * @param {Buffer} buf\r\n * @param {number} pos — current position\r\n * @returns {{ value: number, pos: number }} — the decoded value and new position\r\n */\r\nfunction readDeltaSize(buf, pos) {\r\n  if (pos >= buf.length) {\r\n    throw new GitXRayError(\r\n      `Truncated delta header: expected variable-length integer at position ${pos}`\r\n    );\r\n  }\r\n\r\n  let value = 0;\r\n  let shift = 0;\r\n\r\n  // eslint-disable-next-line no-constant-condition\r\n  while (true) {\r\n    if (pos >= buf.length) {\r\n      throw new GitXRayError(\r\n        `Truncated delta variable-length integer at position ${pos}`\r\n      );\r\n    }\r\n    const byte = buf[pos++];\r\n    value |= (byte & 0x7f) << shift;\r\n    shift += 7;\r\n    if (shift > 28 && (byte & 0x80)) {\r\n      throw new GitXRayError(\r\n        `Unreasonably large delta variable-length integer at position ${pos}`\r\n      );\r\n    }\r\n    if (!(byte & 0x80)) break;\r\n  }\r\n\r\n  // Ensure unsigned 32-bit value\r\n  return { value: value >>> 0, pos };\r\n}\r\n\r\n/**\r\n * Apply a Git delta to a base object to produce the result object.\r\n *\r\n * Delta format:\r\n *   1. Base object size (variable-length encoded)\r\n *   2. Result object size (variable-length encoded)\r\n *   3. Instruction stream:\r\n *      - If MSB = 0: INSERT instruction\r\n *        Next (byte & 0x7f) bytes are literal data to insert.\r\n *        A size of 0 is invalid.\r\n *      - If MSB = 1: COPY instruction\r\n *        The lower 7 bits indicate which offset/size bytes follow:\r\n *        bits 0-3: offset bytes (1, 2, 3, 4 → byte positions 0, 8, 16, 24)\r\n *        bits 4-6: size bytes (1, 2, 3 → byte positions 0, 8, 16)\r\n *        If encoded size is 0, it means 0x10000 (65536).\r\n *\r\n * @param {Buffer} base — base object body\r\n * @param {Buffer} delta — decompressed delta instruction data\r\n * @param {number} objOffset — pack offset (for error messages)\r\n * @param {string} packPath — for error messages\r\n * @returns {Buffer} — reconstructed result object body\r\n */\r\nfunction applyDelta(base, delta, objOffset, packPath) {\r\n  let pos = 0;\r\n\r\n  // Read base size\r\n  const baseSizeResult = readDeltaSize(delta, pos);\r\n  pos = baseSizeResult.pos;\r\n  const declaredBaseSize = baseSizeResult.value;\r\n\r\n  // Read result size\r\n  const resultSizeResult = readDeltaSize(delta, pos);\r\n  pos = resultSizeResult.pos;\r\n  const declaredResultSize = resultSizeResult.value;\r\n\r\n  // Validate base size\r\n  if (declaredBaseSize !== base.length) {\r\n    throw new GitXRayError(\r\n      `Delta base size mismatch at offset ${objOffset} in ${packPath}: ` +\r\n      `delta says ${declaredBaseSize}, actual base is ${base.length}`\r\n    );\r\n  }\r\n\r\n  // Pre-allocate result buffer\r\n  const result = Buffer.allocUnsafe(declaredResultSize);\r\n  let resultPos = 0;\r\n\r\n  // Process instruction stream\r\n  while (pos < delta.length) {\r\n    const cmd = delta[pos++];\r\n\r\n    if (cmd & 0x80) {\r\n      // COPY instruction — copy bytes from base object\r\n      let copyOffset = 0;\r\n      let copySize = 0;\r\n\r\n      // Count how many optional bytes the cmd bits request\r\n      let extraBytes = 0;\r\n      for (let bit = 0; bit < 7; bit++) {\r\n        if (cmd & (1 << bit)) extraBytes++;\r\n      }\r\n      if (pos + extraBytes > delta.length) {\r\n        throw new GitXRayError(\r\n          `Truncated COPY instruction at offset ${objOffset} in ${packPath}: ` +\r\n          `needs ${extraBytes} optional bytes but only ${delta.length - pos} remain`\r\n        );\r\n      }\r\n\r\n      // Read offset bytes (bits 0-3 of cmd indicate which bytes are present)\r\n      if (cmd & 0x01) copyOffset  = delta[pos++];\r\n      if (cmd & 0x02) copyOffset |= delta[pos++] << 8;\r\n      if (cmd & 0x04) copyOffset |= delta[pos++] << 16;\r\n      if (cmd & 0x08) copyOffset |= (delta[pos++] << 24) >>> 0;\r\n\r\n      // Ensure unsigned 32-bit\r\n      copyOffset = copyOffset >>> 0;\r\n\r\n      // Read size bytes (bits 4-6 of cmd indicate which bytes are present)\r\n      if (cmd & 0x10) copySize  = delta[pos++];\r\n      if (cmd & 0x20) copySize |= delta[pos++] << 8;\r\n      if (cmd & 0x40) copySize |= delta[pos++] << 16;\r\n\r\n      // Size of 0 means 0x10000 (65536) per Git spec\r\n      if (copySize === 0) copySize = 0x10000;\r\n\r\n      // Bounds check\r\n      if (copyOffset + copySize > base.length) {\r\n        throw new GitXRayError(\r\n          `Delta COPY out of bounds at offset ${objOffset} in ${packPath}: ` +\r\n          `copying ${copySize} bytes from base offset ${copyOffset}, but base is ${base.length} bytes`\r\n        );\r\n      }\r\n\r\n      base.copy(result, resultPos, copyOffset, copyOffset + copySize);\r\n      resultPos += copySize;\r\n\r\n    } else if (cmd > 0) {\r\n      // INSERT instruction — insert literal bytes from delta\r\n      const insertSize = cmd; // lower 7 bits (MSB is 0, so cmd IS the size)\r\n\r\n      if (pos + insertSize > delta.length) {\r\n        throw new GitXRayError(\r\n          `Delta INSERT truncated at offset ${objOffset} in ${packPath}: ` +\r\n          `wants ${insertSize} bytes but only ${delta.length - pos} remain`\r\n        );\r\n      }\r\n\r\n      delta.copy(result, resultPos, pos, pos + insertSize);\r\n      pos += insertSize;\r\n      resultPos += insertSize;\r\n\r\n    } else {\r\n      // cmd === 0: reserved/invalid instruction\r\n      throw new GitXRayError(\r\n        `Invalid delta instruction (0x00) at offset ${objOffset} in ${packPath}`\r\n      );\r\n    }\r\n  }\r\n\r\n  // Validate result size\r\n  if (resultPos !== declaredResultSize) {\r\n    throw new GitXRayError(\r\n      `Delta result size mismatch at offset ${objOffset} in ${packPath}: ` +\r\n      `declared ${declaredResultSize}, reconstructed ${resultPos}`\r\n    );\r\n  }\r\n\r\n  return result;\r\n}\r\n\r\n// ─── High-Level Packed Object Reader ──────────────────────────────────────────\r\n\r\n// Cache parsed IDX files to avoid re-parsing for every object lookup\r\nlet _idxCache = null;\r\nlet _idxCacheGitDir = null;\r\nlet _packBufCache = new Map();\r\n\r\n/**\r\n * Get or create cached IDX data for a gitDir.\r\n * @param {string} gitDir\r\n * @returns {{ idx: ParsedIdx, packPath: string }[]}\r\n */\r\nfunction getPackIndices(gitDir) {\r\n  if (_idxCacheGitDir === gitDir && _idxCache) {\r\n    return _idxCache;\r\n  }\r\n\r\n  const packFiles = discoverPackFiles(gitDir);\r\n  const indices = [];\r\n\r\n  for (const { idxPath, packPath } of packFiles) {\r\n    try {\r\n      const idx = parseIdx(idxPath);\r\n      indices.push({ idx, packPath });\r\n    } catch (err) {\r\n      // If an IDX is malformed, skip it but don't crash the whole analysis\r\n      if (err instanceof GitXRayError) {\r\n        continue;\r\n      }\r\n      throw err;\r\n    }\r\n  }\r\n\r\n  _idxCache = indices;\r\n  _idxCacheGitDir = gitDir;\r\n  return indices;\r\n}\r\n\r\n/**\r\n * Get or cache a pack file buffer.\r\n * @param {string} packPath\r\n * @returns {Buffer}\r\n */\r\nfunction getPackBuffer(packPath) {\r\n  if (_packBufCache.has(packPath)) {\r\n    return _packBufCache.get(packPath);\r\n  }\r\n\r\n  let buf;\r\n  try {\r\n    buf = fs.readFileSync(packPath);\r\n  } catch (err) {\r\n    throw new GitXRayError(`Failed to read pack file ${packPath}: ${err.message}`);\r\n  }\r\n\r\n  // Validate pack header\r\n  readPackHeader(buf, packPath);\r\n\r\n  _packBufCache.set(packPath, buf);\r\n  return buf;\r\n}\r\n\r\n/**\r\n * Read an object from packfiles.\r\n * Searches all IDX files for the hash, then reads from the corresponding pack.\r\n *\r\n * @param {string} gitDir — path to the .git directory\r\n * @param {string} hash — 40-char hex SHA-1\r\n * @param {Function} [resolveBase] — resolver for REF_DELTA bases (usually readObject)\r\n * @param {number} [depth] — current delta chain depth\r\n * @returns {{ type: string, size: number, body: Buffer } | null}\r\n */\r\nfunction readPackedObject(gitDir, hash, resolveBase, depth) {\r\n  const indices = getPackIndices(gitDir);\r\n\r\n  for (const { idx, packPath } of indices) {\r\n    const offset = idxLookup(idx, hash);\r\n    if (offset === null) continue;\r\n\r\n    // Found in this pack — read the object\r\n    const packBuf = getPackBuffer(packPath);\r\n    const visiting = new Set();\r\n    return readPackObject(packBuf, offset, packPath, resolveBase, gitDir, visiting, depth || 0);\r\n  }\r\n\r\n  return null; // Not found in any pack\r\n}\r\n\r\n/**\r\n * Clear internal caches. Useful for testing when analyzing multiple repos.\r\n */\r\nfunction clearPackCache() {\r\n  _idxCache = null;\r\n  _idxCacheGitDir = null;\r\n  _packBufCache = new Map();\r\n}\r\n\r\n// ─── Exports ──────────────────────────────────────────────────────────────────\r\n\r\nmodule.exports = {\r\n  discoverPackFiles,\r\n  parseIdx,\r\n  idxLookup,\r\n  readPackHeader,\r\n  readPackObject,\r\n  readPackedObject,\r\n  readDeltaSize,\r\n  applyDelta,\r\n  clearPackCache,\r\n  // Constants for testing\r\n  OBJ_COMMIT,\r\n  OBJ_TREE,\r\n  OBJ_BLOB,\r\n  OBJ_TAG,\r\n  OBJ_OFS_DELTA,\r\n  OBJ_REF_DELTA,\r\n  MAX_DELTA_DEPTH,\r\n};\r\n",
  "git/walker.js": "const { readObject, parseCommit, parseTree } = require('./objects.js');\r\n\r\n/**\r\n * Walk the commit graph via BFS from one or more starting hashes.\r\n * Returns commits in reverse-chronological order (newest first).\r\n *\r\n * Uses readObject() which transparently handles both loose and packed objects.\r\n * Tracks how many objects could not be read (genuinely missing/corrupt).\r\n *\r\n * @param {string} gitDir\r\n * @param {string[]} startHashes — branch tips to start from\r\n * @returns {{ commits: ParsedCommit[], skippedCount: number }}\r\n */\r\nfunction walkCommits(gitDir, startHashes) {\r\n  const visited = new Set();\r\n  const commits = [];\r\n  const queue = [...startHashes];\r\n  let skippedCount = 0;\r\n\r\n  while (queue.length > 0) {\r\n    const hash = queue.shift();\r\n\r\n    if (visited.has(hash)) continue;\r\n    visited.add(hash);\r\n\r\n    const obj = readObject(gitDir, hash);\r\n    if (!obj) {\r\n      // Object genuinely missing (not loose, not in any pack)\r\n      skippedCount++;\r\n      continue;\r\n    }\r\n\r\n    if (obj.type !== 'commit') continue;\r\n\r\n    let commit;\r\n    try {\r\n      commit = parseCommit(hash, obj.body);\r\n    } catch {\r\n      // Corrupted commit — skip it\r\n      continue;\r\n    }\r\n\r\n    commits.push(commit);\r\n\r\n    // Enqueue parent commits\r\n    for (const parentHash of commit.parents) {\r\n      if (!visited.has(parentHash)) {\r\n        queue.push(parentHash);\r\n      }\r\n    }\r\n  }\r\n\r\n  // Sort by author timestamp descending (newest first)\r\n  commits.sort((a, b) => b.author.timestamp - a.author.timestamp);\r\n\r\n  return { commits, packedCount: skippedCount };\r\n}\r\n\r\n/**\r\n * Diff two tree SHA-1s recursively to find changed file paths.\r\n *\r\n * Strategy: flatten both trees into { path → hash } maps, then compare.\r\n * This is simpler and more correct than trying to walk both trees in parallel.\r\n *\r\n * For merge commits, we diff against the first parent only (standard convention).\r\n *\r\n * @param {string} gitDir\r\n * @param {string|null} oldTreeHash — parent's root tree (null for root commits)\r\n * @param {string} newTreeHash — this commit's root tree\r\n * @returns {{ added: string[], modified: string[], deleted: string[] }}\r\n */\r\nfunction diffTrees(gitDir, oldTreeHash, newTreeHash) {\r\n  const oldFiles = oldTreeHash ? flattenTree(gitDir, oldTreeHash, '') : new Map();\r\n  const newFiles = flattenTree(gitDir, newTreeHash, '');\r\n\r\n  const added = [];\r\n  const modified = [];\r\n  const deleted = [];\r\n\r\n  // Check for added/modified files\r\n  for (const [filePath, newHash] of newFiles) {\r\n    if (!oldFiles.has(filePath)) {\r\n      added.push(filePath);\r\n    } else if (oldFiles.get(filePath) !== newHash) {\r\n      modified.push(filePath);\r\n    }\r\n  }\r\n\r\n  // Check for deleted files\r\n  for (const [filePath] of oldFiles) {\r\n    if (!newFiles.has(filePath)) {\r\n      deleted.push(filePath);\r\n    }\r\n  }\r\n\r\n  return { added, modified, deleted };\r\n}\r\n\r\n/**\r\n * Recursively flatten a tree object into a map of { filePath → blobHash }.\r\n * Only includes file entries (blobs), not subtrees.\r\n *\r\n * @param {string} gitDir\r\n * @param {string} treeHash\r\n * @param {string} prefix — current directory prefix (e.g., \"src/git/\")\r\n * @returns {Map<string, string>}\r\n */\r\nfunction flattenTree(gitDir, treeHash, prefix) {\r\n  const result = new Map();\r\n\r\n  const obj = readObject(gitDir, treeHash);\r\n  if (!obj || obj.type !== 'tree') {\r\n    return result; // Not found or not a tree — skip silently\r\n  }\r\n\r\n  const entries = parseTree(obj.body);\r\n\r\n  for (const entry of entries) {\r\n    const fullPath = prefix ? `${prefix}/${entry.name}` : entry.name;\r\n\r\n    if (entry.mode === '40000' || entry.mode === '040000') {\r\n      // Subdirectory — recurse\r\n      const subEntries = flattenTree(gitDir, entry.hash, fullPath);\r\n      for (const [k, v] of subEntries) {\r\n        result.set(k, v);\r\n      }\r\n    } else {\r\n      // File (blob, symlink, submodule, etc.)\r\n      result.set(fullPath, entry.hash);\r\n    }\r\n  }\r\n\r\n  return result;\r\n}\r\n\r\n/**\r\n * For each commit, compute which files were changed (added/modified/deleted)\r\n * by diffing its tree against the first parent's tree.\r\n *\r\n * Root commits (no parents) are diffed against an empty tree.\r\n *\r\n * @param {string} gitDir\r\n * @param {ParsedCommit[]} commits — commits from walkCommits()\r\n * @returns {Map<string, { added: string[], modified: string[], deleted: string[] }>}\r\n *   — keyed by commit hash\r\n */\r\nfunction computeAllDiffs(gitDir, commits) {\r\n  const diffs = new Map();\r\n\r\n  // Build a lookup from hash → commit for quick parent resolution\r\n  const commitMap = new Map();\r\n  for (const c of commits) {\r\n    commitMap.set(c.hash, c);\r\n  }\r\n\r\n  for (const commit of commits) {\r\n    // Use first parent for diffs (standard --first-parent convention for merges)\r\n    let parentTreeHash = null;\r\n    if (commit.parents.length > 0) {\r\n      const parentCommit = commitMap.get(commit.parents[0]);\r\n      if (parentCommit) {\r\n        parentTreeHash = parentCommit.tree;\r\n      } else {\r\n        // Parent is packed — we can't diff, record empty diff\r\n        diffs.set(commit.hash, { added: [], modified: [], deleted: [] });\r\n        continue;\r\n      }\r\n    }\r\n\r\n    try {\r\n      const diff = diffTrees(gitDir, parentTreeHash, commit.tree);\r\n      diffs.set(commit.hash, diff);\r\n    } catch {\r\n      // If tree parsing fails, record empty diff rather than crashing\r\n      diffs.set(commit.hash, { added: [], modified: [], deleted: [] });\r\n    }\r\n  }\r\n\r\n  return diffs;\r\n}\r\n\r\nmodule.exports = { walkCommits, diffTrees, flattenTree, computeAllDiffs };\r\n",
  "analytics/churn.js": "/**\n * Compute churn — how many commits touched each file.\n *\n * @param {ParsedCommit[]} commits\n * @param {Map<string, { added: string[], modified: string[], deleted: string[] }>} diffs\n * @returns {{ path: string, touches: number }[]} — sorted by touches descending\n */\nfunction computeChurn(commits, diffs) {\n  const touchCount = new Map(); // path → count\n\n  for (const commit of commits) {\n    const diff = diffs.get(commit.hash);\n    if (!diff) continue;\n\n    const touchedFiles = [...diff.added, ...diff.modified, ...diff.deleted];\n    for (const filePath of touchedFiles) {\n      touchCount.set(filePath, (touchCount.get(filePath) || 0) + 1);\n    }\n  }\n\n  return Array.from(touchCount.entries())\n    .map(([path, touches]) => ({ path, touches }))\n    .sort((a, b) => b.touches - a.touches);\n}\n\nmodule.exports = { computeChurn };\n",
  "analytics/ownership.js": "/**\n * Compute per-file ownership — which authors touched each file and how much.\n *\n * @param {ParsedCommit[]} commits\n * @param {Map<string, { added: string[], modified: string[], deleted: string[] }>} diffs\n * @returns {OwnershipEntry[]} — sorted by path\n */\nfunction computeOwnership(commits, diffs) {\n  // path → { authorKey → { name, email, commits, lastTimestamp } }\n  const fileAuthors = new Map();\n\n  for (const commit of commits) {\n    const diff = diffs.get(commit.hash);\n    if (!diff) continue;\n\n    const authorKey = `${commit.author.name} <${commit.author.email}>`;\n    const touchedFiles = [...diff.added, ...diff.modified];\n    // Note: we don't count deletes toward ownership — if a file is deleted,\n    // it doesn't exist anymore, so ownership is moot.\n\n    for (const filePath of touchedFiles) {\n      if (!fileAuthors.has(filePath)) {\n        fileAuthors.set(filePath, new Map());\n      }\n      const authors = fileAuthors.get(filePath);\n\n      if (!authors.has(authorKey)) {\n        authors.set(authorKey, {\n          name: commit.author.name,\n          email: commit.author.email,\n          commits: 0,\n          lastTimestamp: 0,\n        });\n      }\n\n      const entry = authors.get(authorKey);\n      entry.commits++;\n      entry.lastTimestamp = Math.max(entry.lastTimestamp, commit.author.timestamp);\n    }\n  }\n\n  // Convert to output format\n  const results = [];\n\n  for (const [filePath, authorMap] of fileAuthors) {\n    const totalCommits = Array.from(authorMap.values()).reduce(\n      (sum, a) => sum + a.commits,\n      0\n    );\n\n    const authors = Array.from(authorMap.values())\n      .map((a) => ({\n        name: a.name,\n        email: a.email,\n        commits: a.commits,\n        percentage: (a.commits / totalCommits) * 100,\n      }))\n      .sort((a, b) => b.commits - a.commits);\n\n    const lastTouched = Math.max(\n      ...Array.from(authorMap.values()).map((a) => a.lastTimestamp)\n    );\n\n    results.push({\n      path: filePath,\n      authors,\n      primaryAuthor: {\n        name: authors[0].name,\n        percentage: authors[0].percentage,\n      },\n      distinctAuthors: authors.length,\n      lastTouched,\n    });\n  }\n\n  return results.sort((a, b) => a.path.localeCompare(b.path));\n}\n\nmodule.exports = { computeOwnership };\n",
  "analytics/bus-factor.js": "/**\n * Compute bus-factor — flag files where one author owns more than threshold% of commits.\n * These are the \"if they leave, we're in trouble\" files.\n *\n * @param {OwnershipEntry[]} ownershipData — from computeOwnership()\n * @param {number} threshold — percentage threshold (default 80)\n * @returns {BusFactorEntry[]} — sorted by risk (highest percentage first)\n */\nfunction computeBusFactor(ownershipData, threshold = 80) {\n  const results = [];\n\n  for (const entry of ownershipData) {\n    if (entry.distinctAuthors === 0) continue;\n\n    const topAuthor = entry.authors[0];\n    const atRisk = topAuthor.percentage >= threshold;\n\n    results.push({\n      path: entry.path,\n      topAuthor: topAuthor.name,\n      topAuthorPercentage: topAuthor.percentage,\n      distinctAuthors: entry.distinctAuthors,\n      atRisk,\n    });\n  }\n\n  // Sort: at-risk files first, then by percentage descending\n  return results.sort((a, b) => {\n    if (a.atRisk !== b.atRisk) return a.atRisk ? -1 : 1;\n    return b.topAuthorPercentage - a.topAuthorPercentage;\n  });\n}\n\nmodule.exports = { computeBusFactor };\n",
  "analytics/hotspots.js": "/**\r\n * Risk Hotspots Analyzer\r\n *\r\n * Identifies files that represent engineering or knowledge risk.\r\n *\r\n * Risk Formula:\r\n *   Risk Score = (churn_weight × 0.4) + (ownership_concentration_weight × 0.35) + (recency_weight × 0.25)\r\n *\r\n * Each weight is normalized to 0–100:\r\n *   - Churn: file touch count relative to max churn\r\n *   - Ownership concentration: inverse of bus factor (how much one author dominates)\r\n *   - Recency: how recently the file was last touched\r\n *\r\n * Severity Levels:\r\n *   - CRITICAL: 80–100\r\n *   - HIGH:     60–79\r\n *   - MEDIUM:   40–59\r\n *   - LOW:      0–39\r\n *\r\n * @param {ParsedCommit[]} commits — from walkCommits()\r\n * @param {Map<string, { added, modified, deleted }>} diffs — from computeAllDiffs()\r\n * @returns {Array<{ file, riskScore, severity, churn, ownershipConcentration, recency, primaryRisk }>}\r\n */\r\nfunction computeHotspots(commits, diffs) {\r\n  // Build per-file metrics\r\n  const fileMetrics = new Map();\r\n\r\n  // Iterate through commits in chronological order to track recency\r\n  for (let i = commits.length - 1; i >= 0; i--) {\r\n    const commit = commits[i];\r\n    const diff = diffs.get(commit.hash) || { added: [], modified: [], deleted: [] };\r\n\r\n    const allFiles = new Set([...diff.added, ...diff.modified, ...diff.deleted]);\r\n    for (const file of allFiles) {\r\n      if (!fileMetrics.has(file)) {\r\n        fileMetrics.set(file, {\r\n          path: file,\r\n          touches: 0,\r\n          authorTouches: new Map(),\r\n          lastCommitIndex: i,\r\n          touchDates: [],\r\n        });\r\n      }\r\n\r\n      const metric = fileMetrics.get(file);\r\n      metric.touches++;\r\n      metric.lastCommitIndex = Math.min(metric.lastCommitIndex, i);\r\n      metric.touchDates.push(commit.author.timestamp);\r\n\r\n      const author = commit.author.name;\r\n      metric.authorTouches.set(author, (metric.authorTouches.get(author) || 0) + 1);\r\n    }\r\n  }\r\n\r\n  // Compute normalized weights\r\n  const maxChurn = Math.max(...Array.from(fileMetrics.values()).map((m) => m.touches), 1);\r\n  const now = Math.max(...commits.map((c) => c.author.timestamp), Date.now() / 1000);\r\n  const thirtyDaysAgo = now - 30 * 24 * 60 * 60;\r\n\r\n  const hotspots = [];\r\n\r\n  for (const metric of fileMetrics.values()) {\r\n    // 1. Churn weight: normalized by max churn\r\n    const churnWeight = (metric.touches / maxChurn) * 100;\r\n\r\n    // 2. Ownership concentration weight: max author touch percentage\r\n    const maxAuthorTouches = Math.max(...metric.authorTouches.values(), 1);\r\n    const ownershipConcentration = (maxAuthorTouches / metric.touches) * 100;\r\n    const ownershipWeight = ownershipConcentration; // Higher = riskier\r\n\r\n    // 3. Recency weight: how recently touched\r\n    const lastTouchTime = Math.max(...metric.touchDates, 0);\r\n    const daysSinceLastTouch = Math.max(0, (now - lastTouchTime) / (24 * 60 * 60));\r\n    // Decay: recent = 100, old = lower\r\n    const recencyWeight = Math.max(0, 100 - daysSinceLastTouch * 2); // Decays 2 points per day\r\n\r\n    // Compute composite risk score\r\n    const riskScore = churnWeight * 0.4 + ownershipWeight * 0.35 + recencyWeight * 0.25;\r\n\r\n    // Determine severity\r\n    let severity;\r\n    if (riskScore >= 80) severity = 'CRITICAL';\r\n    else if (riskScore >= 60) severity = 'HIGH';\r\n    else if (riskScore >= 40) severity = 'MEDIUM';\r\n    else severity = 'LOW';\r\n\r\n    // Identify primary risk reason\r\n    const reasons = [];\r\n    if (churnWeight >= 70) reasons.push('High change frequency');\r\n    if (ownershipWeight >= 80) reasons.push('Knowledge concentrated in one author');\r\n    if (recencyWeight >= 70) reasons.push('Recently modified frequently');\r\n\r\n    const primaryRisk = reasons.length > 0 ? reasons[0] : 'Moderate risk profile';\r\n\r\n    hotspots.push({\r\n      file: metric.path,\r\n      riskScore: Math.round(riskScore),\r\n      severity,\r\n      churn: metric.touches,\r\n      ownershipConcentration: Math.round(ownershipConcentration),\r\n      recency: daysSinceLastTouch,\r\n      primaryRisk,\r\n      topAuthor: Array.from(metric.authorTouches.entries()).sort((a, b) => b[1] - a[1])[0],\r\n    });\r\n  }\r\n\r\n  // Sort by risk score descending\r\n  hotspots.sort((a, b) => b.riskScore - a.riskScore);\r\n\r\n  return hotspots;\r\n}\r\n\r\n/**\r\n * Filter hotspots by minimum risk score\r\n * @param {Array} hotspots — from computeHotspots()\r\n * @param {string} minSeverity — \"CRITICAL\", \"HIGH\", \"MEDIUM\", \"LOW\"\r\n * @returns {Array}\r\n */\r\nfunction filterBySeverity(hotspots, minSeverity) {\r\n  const severityMap = { CRITICAL: 4, HIGH: 3, MEDIUM: 2, LOW: 1 };\r\n  const minLevel = severityMap[minSeverity] || 0;\r\n  return hotspots.filter((h) => severityMap[h.severity] >= minLevel);\r\n}\r\n\r\nmodule.exports = { computeHotspots, filterBySeverity };\r\n",
  "analytics/overview.js": "const { computeChurn } = require('./churn.js');\nconst { computeOwnership } = require('./ownership.js');\nconst { computeBusFactor } = require('./bus-factor.js');\nconst { computeHotspots } = require('./hotspots.js');\n\n/**\n * Compute Executive Overview metrics for a repository.\n *\n * Provides:\n * - Basic stats: commits count, contributor count, tracked files count\n * - Overall risk score & severity rating (LOW / MEDIUM / HIGH / CRITICAL)\n * - Knowledge concentration metrics (gini/top author dominance)\n * - Bus-factor alerts (files with high single-author concentration)\n * - Critical files & Top hotspots (risk ranked)\n *\n * @param {string} repoPath\n * @param {ParsedCommit[]} commits\n * @param {Map<string, { added, modified, deleted }>} diffs\n * @param {number} threshold - bus factor threshold (default: 80)\n * @returns {ExecutiveOverview}\n */\nfunction computeOverview(repoPath, commits, diffs, threshold = 80) {\n  const churnList = computeChurn(commits, diffs);\n  const ownershipList = computeOwnership(commits, diffs);\n  const busFactorList = computeBusFactor(ownershipList, threshold);\n  const hotspotsList = computeHotspots(commits, diffs);\n\n  // 1. Contributor count & author distribution\n  const authorSet = new Set();\n  const authorCommitCount = new Map();\n\n  for (const commit of commits) {\n    const authorKey = `${commit.author.name} <${commit.author.email}>`;\n    authorSet.add(authorKey);\n    authorCommitCount.set(authorKey, (authorCommitCount.get(authorKey) || 0) + 1);\n  }\n\n  const contributorCount = authorSet.size;\n  const fileCount = ownershipList.length;\n  const commitCount = commits.length;\n\n  // 2. Bus-factor alerts (files >= threshold)\n  const busFactorAlerts = busFactorList.filter((b) => b.atRisk);\n\n  // 3. Critical & High risk files\n  const criticalFiles = hotspotsList.filter((h) => h.severity === 'CRITICAL');\n  const highRiskFiles = hotspotsList.filter((h) => h.severity === 'HIGH');\n  const topHotspots = hotspotsList.slice(0, 5);\n\n  // 4. Knowledge Concentration calculation\n  // Find top committer across repo and their share of all commits\n  let topCommitter = 'None';\n  let topCommitterCommits = 0;\n  for (const [authorKey, count] of authorCommitCount.entries()) {\n    if (count > topCommitterCommits) {\n      topCommitterCommits = count;\n      topCommitter = authorKey.split(' <')[0];\n    }\n  }\n\n  const topCommitterShare = commitCount > 0 ? (topCommitterCommits / commitCount) * 100 : 0;\n\n  // Average ownership dominance across all files\n  let avgMaxOwnership = 0;\n  if (ownershipList.length > 0) {\n    const sumDominance = ownershipList.reduce((acc, curr) => acc + (curr.primaryAuthor?.percentage || 0), 0);\n    avgMaxOwnership = sumDominance / ownershipList.length;\n  }\n\n  // 5. Overall Repository Risk Scoring (0-100)\n  // Factors:\n  // - Critical & High hotspots ratio\n  // - Bus factor at-risk percentage\n  // - Contributor count & commit distribution\n  let riskScore = 0;\n\n  if (fileCount > 0) {\n    const criticalRatio = criticalFiles.length / fileCount;\n    const highRatio = highRiskFiles.length / fileCount;\n    const atRiskRatio = busFactorAlerts.length / fileCount;\n\n    const hotspotFactor = Math.min(100, (criticalRatio * 100 * 0.5) + (highRatio * 100 * 0.3) + ((topHotspots[0]?.riskScore || 0) * 0.2));\n    const busFactorScore = atRiskRatio * 100;\n    const concentrationScore = avgMaxOwnership;\n\n    riskScore = Math.round(\n      (hotspotFactor * 0.40) +\n      (busFactorScore * 0.35) +\n      (concentrationScore * 0.25)\n    );\n  }\n\n  let overallRisk = 'LOW';\n  if (riskScore >= 75) overallRisk = 'CRITICAL';\n  else if (riskScore >= 50) overallRisk = 'HIGH';\n  else if (riskScore >= 25) overallRisk = 'MEDIUM';\n\n  return {\n    repository: repoPath,\n    commitCount,\n    contributorCount,\n    fileCount,\n    overallRisk,\n    riskScore,\n    knowledgeConcentration: {\n      topCommitter,\n      topCommitterShare: Math.round(topCommitterShare * 10) / 10,\n      avgMaxOwnership: Math.round(avgMaxOwnership * 10) / 10,\n      concentrationLevel: avgMaxOwnership >= 80 ? 'HIGH' : avgMaxOwnership >= 50 ? 'MODERATE' : 'BALANCED',\n    },\n    busFactorAlerts: {\n      threshold,\n      atRiskCount: busFactorAlerts.length,\n      percentage: fileCount > 0 ? Math.round((busFactorAlerts.length / fileCount) * 1000) / 10 : 0,\n      topAlerts: busFactorAlerts.slice(0, 5),\n    },\n    criticalFiles: criticalFiles.map((c) => ({\n      file: c.file,\n      riskScore: c.riskScore,\n      primaryRisk: c.primaryRisk,\n    })),\n    topHotspots: topHotspots.map((h) => ({\n      file: h.file,\n      riskScore: h.riskScore,\n      severity: h.severity,\n      churn: h.churn,\n      ownershipConcentration: Math.round(h.ownershipConcentration),\n      primaryRisk: h.primaryRisk,\n    })),\n  };\n}\n\nmodule.exports = { computeOverview };\n",
  "analytics/complexity.js": "const fs = require('node:fs');\r\nconst path = require('node:path');\r\n\r\n/**\r\n * Structural Complexity Analyzer\r\n *\r\n * Detects structural patterns in source code:\r\n * - if/else branches\r\n * - loops (for, while, do-while, foreach)\r\n * - switch cases\r\n * - catch blocks\r\n * - logical operators\r\n * - ternary operators\r\n * - function/method declarations\r\n * - nesting depth\r\n *\r\n * Complexity Score Calculation:\r\n *   Base = (branches + loops + switches + catches + ternaries) × 1\r\n *   Operators = logical operators × 0.5\r\n *   Nesting = max nesting depth × 2\r\n *   Functions = function count (context only, not added to score)\r\n *\r\n *   Normalized Score (0–100):\r\n *     score = min(100, (base + operators + nesting) / scaleFactor)\r\n *\r\n * This is NOT cyclomatic complexity or a universal metric.\r\n * It is a simple heuristic for identifying structurally complex files.\r\n *\r\n * @param {string} filePath — absolute path to the source file\r\n * @returns {{ file, score, complexity, branches, loops, switches, catches, ternaries, logicalOps, maxDepth, functions, language }}\r\n */\r\nfunction analyzeComplexity(filePath) {\r\n  const content = fs.readFileSync(filePath, 'utf8');\r\n  const language = detectLanguage(filePath);\r\n\r\n  // Remove comments to avoid counting keywords inside them\r\n  const stripped = stripComments(content, language);\r\n\r\n  // Count structural patterns\r\n  const branches = (stripped.match(/\\b(if|else\\s+if|else)\\b/g) || []).length;\r\n  const switches = (stripped.match(/\\bswitch\\b/g) || []).length;\r\n  const cases = (stripped.match(/\\bcase\\b/g) || []).length;\r\n  const loops = (stripped.match(/\\b(for|while|do|foreach)\\b/g) || []).length;\r\n  const catches = (stripped.match(/\\bcatch\\b/g) || []).length;\r\n  const ternaries = (stripped.match(/\\?[^?]*:/g) || []).length;\r\n  const logicalOps = (stripped.match(/(?:&&|\\|\\||!)/g) || []).length;\r\n  const functions = (stripped.match(/\\b(?:function|def|fn|=>|async\\s+\\w+|async\\s*\\()\\b/g) || []).length;\r\n\r\n  // Calculate nesting depth (simple approximation)\r\n  const maxDepth = calculateMaxNesting(stripped);\r\n\r\n  // Compute base complexity score\r\n  const base = branches + switches + cases + loops + catches + ternaries;\r\n  const operators = logicalOps * 0.5;\r\n  const nesting = Math.max(0, maxDepth - 1) * 2; // Penalize deep nesting\r\n\r\n  const rawScore = base + operators + nesting;\r\n\r\n  // Normalize to 0–100\r\n  // Scale factor: aim for a reasonably complex file (~10 branches+depth) to score ~30–40\r\n  const scaleFactor = 1.0;\r\n  const normalizedScore = Math.min(100, Math.round(rawScore * scaleFactor));\r\n\r\n  // Complexity level\r\n  let complexity;\r\n  if (normalizedScore >= 70) complexity = 'VERY HIGH';\r\n  else if (normalizedScore >= 50) complexity = 'HIGH';\r\n  else if (normalizedScore >= 30) complexity = 'MEDIUM';\r\n  else if (normalizedScore >= 10) complexity = 'LOW';\r\n  else complexity = 'TRIVIAL';\r\n\r\n  return {\r\n    file: filePath,\r\n    score: normalizedScore,\r\n    complexity,\r\n    branches,\r\n    loops,\r\n    switches,\r\n    cases,\r\n    catches,\r\n    ternaries,\r\n    logicalOps,\r\n    maxDepth,\r\n    functions,\r\n    language,\r\n    raw: { base, operators, nesting },\r\n  };\r\n}\r\n\r\n/**\r\n * Detect language from file extension\r\n * @param {string} filePath\r\n * @returns {string}\r\n */\r\nfunction detectLanguage(filePath) {\r\n  const ext = path.extname(filePath).toLowerCase();\r\n  const langMap = {\r\n    '.js': 'JavaScript',\r\n    '.ts': 'TypeScript',\r\n    '.jsx': 'JSX',\r\n    '.tsx': 'TSX',\r\n    '.py': 'Python',\r\n    '.java': 'Java',\r\n    '.go': 'Go',\r\n    '.rs': 'Rust',\r\n    '.cpp': 'C++',\r\n    '.c': 'C',\r\n    '.cs': 'C#',\r\n    '.php': 'PHP',\r\n    '.rb': 'Ruby',\r\n    '.swift': 'Swift',\r\n    '.kt': 'Kotlin',\r\n  };\r\n  return langMap[ext] || 'Unknown';\r\n}\r\n\r\n/**\r\n * Strip comments from code\r\n * Handles:\r\n * - // single-line comments\r\n * - block comments (multi-line)\r\n * - # comments (Python, Shell)\r\n * - -- comments (SQL)\r\n *\r\n * @param {string} content\r\n * @param {string} language\r\n * @returns {string}\r\n */\r\nfunction stripComments(content, language) {\r\n  let result = content;\r\n\r\n  // Remove // comments\r\n  result = result.replace(/\\/\\/.*$/gm, ' ');\r\n\r\n  // Remove /* */ comments\r\n  result = result.replace(/\\/\\*[\\s\\S]*?\\*\\//g, ' ');\r\n\r\n  // Remove # comments (Python, shell)\r\n  result = result.replace(/#.*$/gm, ' ');\r\n\r\n  // Remove -- comments (SQL)\r\n  result = result.replace(/--.*$/gm, ' ');\r\n\r\n  // Remove strings to avoid counting keywords in string literals\r\n  // Remove \"...\" strings\r\n  result = result.replace(/\"(?:\\\\\"|[^\"])*\"/g, ' ');\r\n\r\n  // Remove '...' strings\r\n  result = result.replace(/'(?:\\\\'|[^'])*'/g, ' ');\r\n\r\n  // Remove `...` strings (template literals)\r\n  result = result.replace(/`(?:\\\\`|[^`])*`/g, ' ');\r\n\r\n  return result;\r\n}\r\n\r\n/**\r\n * Calculate maximum nesting depth\r\n * Counts { } { } nesting (simple brace matching)\r\n *\r\n * @param {string} content\r\n * @returns {number}\r\n */\r\nfunction calculateMaxNesting(content) {\r\n  let maxDepth = 0;\r\n  let currentDepth = 0;\r\n\r\n  for (let i = 0; i < content.length; i++) {\r\n    if (content[i] === '{') {\r\n      currentDepth++;\r\n      maxDepth = Math.max(maxDepth, currentDepth);\r\n    } else if (content[i] === '}') {\r\n      currentDepth = Math.max(0, currentDepth - 1);\r\n    }\r\n  }\r\n\r\n  return maxDepth;\r\n}\r\n\r\n/**\r\n * Analyze complexity for all files in a directory/repository\r\n * @param {string} dirPath — absolute path to directory\r\n * @returns {Array<{ file, score, complexity, ... }>}\r\n */\r\nfunction analyzeDirectoryComplexity(dirPath) {\r\n  const results = [];\r\n  const supportedExts = new Set([\r\n    '.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.go', '.rs',\r\n    '.cpp', '.c', '.cs', '.php', '.rb', '.swift', '.kt',\r\n  ]);\r\n\r\n  function walkDir(dir) {\r\n    try {\r\n      const entries = fs.readdirSync(dir, { withFileTypes: true });\r\n      for (const entry of entries) {\r\n        const fullPath = path.join(dir, entry.name);\r\n\r\n        // Skip common non-source directories\r\n        if (entry.isDirectory()) {\r\n          if (!entry.name.startsWith('.') && entry.name !== 'node_modules') {\r\n            walkDir(fullPath);\r\n          }\r\n        } else if (entry.isFile()) {\r\n          const ext = path.extname(entry.name).toLowerCase();\r\n          if (supportedExts.has(ext)) {\r\n            try {\r\n              const analysis = analyzeComplexity(fullPath);\r\n              results.push(analysis);\r\n            } catch {\r\n              // Skip files that can't be read\r\n            }\r\n          }\r\n        }\r\n      }\r\n    } catch {\r\n      // Skip directories that can't be read\r\n    }\r\n  }\r\n\r\n  walkDir(dirPath);\r\n\r\n  // Sort by score descending\r\n  results.sort((a, b) => b.score - a.score);\r\n\r\n  return results;\r\n}\r\n\r\nmodule.exports = { analyzeComplexity, analyzeDirectoryComplexity, detectLanguage, stripComments, calculateMaxNesting };\r\n",
  "ui/core.js": "const util = require('node:util');\n\n/**\n * Terminal UI core utilities for zero-dependency agentic CLIs.\n */\n\nconst colorEnabled =\n  !process.env.NO_COLOR &&\n  process.env.TERM !== 'dumb' &&\n  (process.stdout.isTTY !== false || process.env.FORCE_COLOR === '1');\n\n/**\n * Apply ANSI text styling.\n * @param {string} styleName - color/style name supported by Node's util.styleText or basic ansi\n * @param {string} text\n */\nfunction style(styleName, text) {\n  if (!colorEnabled) return String(text);\n  if (typeof util.styleText === 'function') {\n    try {\n      return util.styleText(styleName, String(text));\n    } catch {\n      // fallback if style name is unknown in util.styleText\n    }\n  }\n  return String(text);\n}\n\n/**\n * Strip ANSI escape codes to measure visible string width accurately.\n * @param {string} str\n */\nfunction stripAnsi(str) {\n  // eslint-disable-next-line no-control-regex\n  return String(str || '').replace(/\\x1b\\[[0-9;]*m/g, '');\n}\n\n/**\n * Get visual length of string without ANSI codes.\n * @param {string} str\n */\nfunction visibleLength(str) {\n  return stripAnsi(str).length;\n}\n\n/**\n * Get current terminal width with safe default fallback.\n * @param {number} fallback\n */\nfunction getTerminalWidth(fallback = 80) {\n  return process.stdout.columns && process.stdout.columns > 20\n    ? process.stdout.columns\n    : fallback;\n}\n\n/**\n * Pad a string to target width, ANSI-safe.\n * @param {string} str\n * @param {number} width\n * @param {'left'|'right'|'center'} align\n */\nfunction pad(str, width, align = 'right') {\n  const s = String(str || '');\n  const len = visibleLength(s);\n  if (len >= width) return s;\n  const diff = width - len;\n  if (align === 'left') {\n    return ' '.repeat(diff) + s;\n  }\n  if (align === 'center') {\n    const left = Math.floor(diff / 2);\n    const right = diff - left;\n    return ' '.repeat(left) + s + ' '.repeat(right);\n  }\n  return s + ' '.repeat(diff);\n}\n\nfunction padRight(str, width) {\n  return pad(str, width, 'right');\n}\n\nfunction padLeft(str, width) {\n  return pad(str, width, 'left');\n}\n\nfunction padCenter(str, width) {\n  return pad(str, width, 'center');\n}\n\n/**\n * Truncate string to max visible length with optional ellipsis.\n * @param {string} str\n * @param {number} max\n * @param {string} ellipsis\n */\nfunction truncate(str, max, ellipsis = '…') {\n  const s = String(str || '');\n  if (visibleLength(s) <= max) return s;\n  let trimmed = s;\n  const target = Math.max(1, max - visibleLength(ellipsis));\n  while (visibleLength(trimmed) > target && trimmed.length > 0) {\n    trimmed = trimmed.slice(0, -1);\n  }\n  return trimmed + ellipsis;\n}\n\n/**\n * Box drawing border characters.\n */\nconst BOX = {\n  rounded: {\n    tl: '╭', tr: '╮', bl: '╰', br: '╯',\n    h: '─', v: '│',\n    vl: '├', vr: '┤', ht: '┬', hb: '┴',\n    x: '┼'\n  },\n  single: {\n    tl: '┌', tr: '┐', bl: '└', br: '┘',\n    h: '─', v: '│',\n    vl: '├', vr: '┤', ht: '┬', hb: '┴',\n    x: '┼'\n  },\n  double: {\n    tl: '╔', tr: '╗', bl: '╚', br: '╝',\n    h: '═', v: '║',\n    vl: '╠', vr: '╣', ht: '╦', hb: '╩',\n    x: '╬'\n  },\n  ascii: {\n    tl: '+', tr: '+', bl: '+', br: '+',\n    h: '-', v: '|',\n    vl: '+', vr: '+', ht: '+', hb: '+',\n    x: '+'\n  }\n};\n\n/**\n * Status badges & icons.\n */\nconst BADGES = {\n  critical: () => style('bold', style('red', '[ CRITICAL ]')),\n  high: () => style('bold', style('yellow', '[ HIGH ]')),\n  medium: () => style('bold', style('cyan', '[ MEDIUM ]')),\n  low: () => style('bold', style('green', '[ LOW ]')),\n  healthy: () => style('bold', style('green', '[ HEALTHY ]')),\n  warning: () => style('bold', style('yellow', '[ WARNING ]')),\n  alert: () => style('bold', style('red', '[ ALERT ]')),\n  live: () => style('bold', style('green', '[ LIVE ]')),\n  info: () => style('bold', style('cyan', '[ INFO ]')),\n};\n\n/**\n * Format a progress / gauge bar.\n * @param {number} percent - 0 to 100\n * @param {number} width - character width\n * @param {Object} opts\n */\nfunction renderBar(percent, width = 20, opts = {}) {\n  const p = Math.max(0, Math.min(100, percent));\n  const fillWidth = Math.round((p / 100) * width);\n  const emptyWidth = width - fillWidth;\n  const fillChar = opts.fillChar || '█';\n  const emptyChar = opts.emptyChar || '░';\n\n  let coloredFill;\n  if (p >= 80) coloredFill = style('red', fillChar.repeat(fillWidth));\n  else if (p >= 50) coloredFill = style('yellow', fillChar.repeat(fillWidth));\n  else coloredFill = style('green', fillChar.repeat(fillWidth));\n\n  return coloredFill + style('dim', emptyChar.repeat(emptyWidth));\n}\n\nmodule.exports = {\n  colorEnabled,\n  style,\n  stripAnsi,\n  visibleLength,\n  getTerminalWidth,\n  pad,\n  padRight,\n  padLeft,\n  padCenter,\n  truncate,\n  BOX,\n  BADGES,\n  renderBar,\n};\n",
  "ui/logo.js": "const { style } = require('./core.js');\n\n/**\n * ASCII wordmark for \"GIT X-RAY\".\n */\nconst WORDMARK_LINES = [\n  '  ██████╗   ██╗ ████████╗    ██╗  ██╗ ██████╗  █████╗ ██╗   ██╗',\n  '██╔═════╝   ██║ ╚══██╔══╝    ╚██╗██╔╝ ██╔══██╗██╔══██╗╚██╗ ██╔╝',\n  '██║   ████╗ ██║    ██║        ╚███╔╝  ██████╔╝███████║ ╚████╔╝ ',\n  '██║   ╚═██║ ██║    ██║        ██╔██╗  ██╔══██╗██╔══██║  ╚██╔╝  ',\n  '╚████████╔╝ ██║    ██║       ██╔╝ ██╗ ██║  ██║██║  ██║   ██║   ',\n  ' ╚═══════╝  ╚═╝    ╚═╝       ╚═╝  ╚═╝ ╚═╝  ╚═╝╚═╝  ╚═╝   ╚═╝   ',\n];\n\n/**\n * Compact single-line header for narrow viewports (< 50 cols).\n */\nconst COMPACT_WORDMARK = [\n  '  ◈ GIT X-RAY · Codebase Forensics',\n];\n\n/**\n * Render the Git X-Ray logo header.\n * @param {Object} opts\n * @param {boolean} [opts.showSubtitle=true]\n */\nfunction renderLogo(opts = {}) {\n  const termWidth = process.stdout.columns || 80;\n  const showSubtitle = opts.showSubtitle !== false;\n\n  if (termWidth < 50) {\n    const lines = [style('bold', style('green', COMPACT_WORDMARK[0]))];\n    if (showSubtitle) {\n      lines.push(style('dim', '    Zero-dependency history intelligence'));\n    }\n    return lines.join('\\n');\n  }\n\n  const lines = Array.isArray(WORDMARK_LINES)\n    ? WORDMARK_LINES\n    : String(WORDMARK_LINES).split('\\n');\n\n  const coloredWordmark = lines\n    .map((line) => style('bold', style('green', line)))\n    .join('\\n');\n\n  if (!showSubtitle) {\n    return coloredWordmark;\n  }\n\n  const subtitle = `  ${style('dim', 'Zero-dependency codebase forensics')} ${style('cyan', 'v1.0.0')}`;\n  return `${coloredWordmark}\\n${subtitle}`;\n}\n\nmodule.exports = {\n  WORDMARK_LINES,\n  renderLogo,\n};\n",
  "ui/components.js": "const {\n  style,\n  stripAnsi,\n  visibleLength,\n  getTerminalWidth,\n  pad,\n  padRight,\n  padLeft,\n  padCenter,\n  truncate,\n  BOX,\n  BADGES,\n  renderBar,\n} = require('./core.js');\n\n/**\n * Render a bordered panel/card with responsive width.\n * @param {Object} opts\n * @param {string} [opts.title] - panel header title\n * @param {string} [opts.badge] - status badge string\n * @param {string[]} opts.lines - body text lines\n * @param {number} [opts.width] - explicit width (default auto fits terminal)\n * @param {'rounded'|'single'|'double'|'ascii'} [opts.borderStyle]\n * @param {string} [opts.borderColor]\n */\nfunction renderPanel({\n  title,\n  badge,\n  lines = [],\n  width,\n  borderStyle = 'rounded',\n  borderColor = 'cyan',\n}) {\n  const b = BOX[borderStyle] || BOX.rounded;\n  const termWidth = getTerminalWidth(80);\n  const targetWidth = Math.min(termWidth - 2, width || Math.max(76, termWidth - 4));\n  const innerWidth = targetWidth - 2;\n\n  const result = [];\n\n  // Top border with title and optional badge\n  let topHeader = '';\n  if (title) {\n    const titleText = ` ${title} `;\n    const badgeText = badge ? ` ${badge} ` : '';\n    const available = innerWidth - visibleLength(titleText) - visibleLength(badgeText);\n    if (available >= 2) {\n      topHeader = `${titleText}${b.h.repeat(available)}${badgeText}`;\n    } else {\n      topHeader = truncate(titleText, innerWidth);\n    }\n  }\n\n  const topRemainder = Math.max(0, innerWidth - visibleLength(topHeader));\n  const topBorder = style(borderColor, `${b.tl}${topHeader}${b.h.repeat(topRemainder)}${b.tr}`);\n  result.push(topBorder);\n\n  // Content lines\n  for (const line of lines) {\n    const content = padRight(truncate(line, innerWidth), innerWidth);\n    result.push(`${style(borderColor, b.v)}${content}${style(borderColor, b.v)}`);\n  }\n\n  // Bottom border\n  const bottomBorder = style(borderColor, `${b.bl}${b.h.repeat(innerWidth)}${b.br}`);\n  result.push(bottomBorder);\n\n  return result.join('\\n');\n}\n\n/**\n * Render key-value metric summary grid inside a panel.\n * @param {Object} opts\n * @param {string} opts.title\n * @param {string} opts.repoPath\n * @param {Array<{label: string, value: string|number, color?: string}>} opts.metrics\n * @param {string} [opts.status]\n */\nfunction renderExecutiveCard({\n  title = 'Repository Executive Overview',\n  repoPath = process.cwd(),\n  metrics = [],\n  status = 'Healthy',\n}) {\n  const innerLines = [];\n\n  const statusBadge = BADGES[status.toLowerCase()] ? BADGES[status.toLowerCase()]() : `[ ${status} ]`;\n  \n  // Header line\n  innerLines.push(` ${style('bold', style('green', 'GIT X-RAY'))}  ${style('dim', '•')}  ${style('bold', title)}  ${statusBadge}`);\n  innerLines.push(` ${style('dim', 'repo:')} ${style('bold', repoPath)}`);\n  innerLines.push('');\n\n  // Metric pills formatted cleanly\n  const pillStr = metrics\n    .map((m) => {\n      const val = m.color ? style(m.color, String(m.value)) : style('bold', String(m.value));\n      return `${style('dim', m.label)}: ${val}`;\n    })\n    .join(style('dim', '   │   '));\n\n  innerLines.push(` ${pillStr}`);\n\n  return renderPanel({\n    lines: innerLines,\n    borderColor: 'cyan',\n  });\n}\n\n/**\n * Render clean, ANSI-aware aligned table with responsive column width management.\n * @param {string[]} headers\n * @param {string[][]} rows\n * @param {Object} opts\n * @param {string[]} [opts.alignments] - array of 'left'|'right'|'center'\n * @param {string} [opts.headerColor] - header color\n */\nfunction renderTable(headers, rows, opts = {}) {\n  const headerColor = opts.headerColor || 'cyan';\n  const alignments = opts.alignments || headers.map(() => 'right');\n  const termWidth = getTerminalWidth(80);\n  const maxTableWidth = Math.min(termWidth - 2, 100);\n\n  // Compute maximum content width per column\n  const colWidths = headers.map((h, i) => {\n    let max = visibleLength(h);\n    for (const row of rows) {\n      if (row[i] !== undefined) {\n        max = Math.max(max, visibleLength(String(row[i])));\n      }\n    }\n    return max;\n  });\n\n  // Check if columns exceed terminal width and compress first column (usually file path) if needed\n  let totalWidth = colWidths.reduce((a, b) => a + b, 0) + (headers.length - 1) * 3;\n  if (totalWidth > maxTableWidth && colWidths.length > 1) {\n    const overflow = totalWidth - maxTableWidth;\n    colWidths[0] = Math.max(20, colWidths[0] - overflow);\n  }\n\n  const lines = [];\n\n  // Header row\n  const headerCells = headers.map((h, i) => {\n    const padded = pad(h, colWidths[i], alignments[i]);\n    return style('bold', style(headerColor, padded));\n  });\n  lines.push(headerCells.join(style('dim', ' │ ')));\n\n  // Divider row\n  const dividers = colWidths.map((w) => '─'.repeat(w));\n  lines.push(style('dim', dividers.join('─┼─')));\n\n  // Data rows\n  for (const row of rows) {\n    const rowCells = headers.map((_, i) => {\n      const rawCell = row[i] !== undefined ? String(row[i]) : '';\n      const cellText = i === 0 ? truncate(rawCell, colWidths[i]) : rawCell;\n      return pad(cellText, colWidths[i], alignments[i]);\n    });\n    lines.push(rowCells.join(style('dim', ' │ ')));\n  }\n\n  return lines.join('\\n');\n}\n\n/**\n * Render a section header banner.\n * @param {string} title\n * @param {string} [icon]\n */\nfunction renderSection(title, icon = '▶') {\n  return `\\n${style('bold', style('cyan', `${icon} ${title}`))}`;\n}\n\nmodule.exports = {\n  renderPanel,\n  renderExecutiveCard,\n  renderTable,\n  renderSection,\n};\n",
  "ui/spinner.js": "const { style } = require('./core.js');\n\n/**\n * ANSI braille/spinner frames for CLI interactions.\n */\nconst SPINNERS = {\n  dots: ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'],\n  pulse: ['█', '▓', '▒', '░', '▒', '▓'],\n  arrows: ['←', '↖', '↑', '↗', '→', '↘', '↓', '↙'],\n  bars: [' ', '▃', '▄', '▅', '▆', '▇', '█', '▇', '▆', '▅', '▄', '▃'],\n};\n\n/**\n * Zero-dependency live terminal progress/spinner display.\n */\nclass TerminalSpinner {\n  /**\n   * @param {string} text - initial status text\n   * @param {Object} [opts]\n   * @param {string} [opts.spinner='dots']\n   * @param {string} [opts.color='cyan']\n   */\n  constructor(text, opts = {}) {\n    this.text = text;\n    this.frames = SPINNERS[opts.spinner] || SPINNERS.dots;\n    this.color = opts.color || 'cyan';\n    this.frameIndex = 0;\n    this.timer = null;\n    this.isTTY = process.stdout.isTTY && !process.env.CI;\n  }\n\n  /**\n   * Start spinning animation in TTY environments.\n   */\n  start() {\n    if (!this.isTTY) {\n      process.stdout.write(`• ${this.text}...\\n`);\n      return this;\n    }\n\n    // Hide cursor\n    process.stdout.write('\\u001b[?25l');\n    this.render();\n\n    this.timer = setInterval(() => {\n      this.frameIndex = (this.frameIndex + 1) % this.frames.length;\n      this.render();\n    }, 80);\n\n    return this;\n  }\n\n  /**\n   * Update message.\n   * @param {string} text\n   */\n  update(text) {\n    this.text = text;\n    if (this.isTTY) {\n      this.render();\n    }\n  }\n\n  render() {\n    const frame = style('bold', style(this.color, this.frames[this.frameIndex]));\n    process.stdout.write(`\\r\\u001b[K${frame} ${this.text}`);\n  }\n\n  /**\n   * Stop spinner with success mark.\n   * @param {string} [text]\n   */\n  succeed(text) {\n    this.stop();\n    const msg = text || this.text;\n    const mark = style('bold', style('green', '✓'));\n    if (this.isTTY) {\n      process.stdout.write(`\\r\\u001b[K${mark} ${msg}\\n`);\n    } else {\n      process.stdout.write(`✓ ${msg}\\n`);\n    }\n  }\n\n  /**\n   * Stop spinner with failure mark.\n   * @param {string} [text]\n   */\n  fail(text) {\n    this.stop();\n    const msg = text || this.text;\n    const mark = style('bold', style('red', '✗'));\n    if (this.isTTY) {\n      process.stdout.write(`\\r\\u001b[K${mark} ${msg}\\n`);\n    } else {\n      process.stdout.write(`✗ ${msg}\\n`);\n    }\n  }\n\n  /**\n   * Stop spinner and restore cursor.\n   */\n  stop() {\n    if (this.timer) {\n      clearInterval(this.timer);\n      this.timer = null;\n    }\n    if (this.isTTY) {\n      // Show cursor\n      process.stdout.write('\\u001b[?25h');\n    }\n  }\n}\n\nmodule.exports = {\n  SPINNERS,\n  TerminalSpinner,\n};\n",
  "ui/dashboard.js": "const {\n  style,\n  stripAnsi,\n  visibleLength,\n  getTerminalWidth,\n  padRight,\n  padLeft,\n  truncate,\n  BOX,\n} = require('./core.js');\nconst { renderLogo } = require('./logo.js');\n\n/**\n * Build menu items reframed around user questions.\n */\nfunction buildDashboardMenu({ repoPath = process.cwd(), metrics = {}, overview = null } = {}) {\n  const topHotspot = overview?.topHotspots?.[0];\n  const atRiskCount = overview?.busFactorAlerts?.atRiskCount ?? 0;\n  const criticalCount = overview?.criticalFiles?.length ?? 0;\n\n  const items = [\n    {\n      id: 'overview',\n      label: 'Repository Health',\n      question: 'What is the overall health & risk score?',\n      description: 'High-level risk diagnosis, contributors, and key findings',\n      accent: 'cyan',\n      preview: [\n        `Risk Status:    ${overview?.overallRisk ? style(overview.overallRisk === 'CRITICAL' ? 'red' : 'yellow', `${overview.overallRisk} (${overview.riskScore}/100)`) : '—'}`,\n        `Contributors:   ${String(metrics.contributors ?? '—')} active authors`,\n        `Tracked Files:  ${String(metrics.files ?? '—')} files across repository`,\n      ],\n    },\n    {\n      id: 'hotspots',\n      label: 'Where Is The Risk?',\n      question: 'Which files combine churn, dominance & recency risk?',\n      description: 'Ranked hotspots and fragile files needing attention',\n      accent: 'red',\n      preview: [\n        `Critical Files: ${style('bold', style(criticalCount > 0 ? 'red' : 'green', `${criticalCount} critical`))}`,\n        `Top Threat:     ${topHotspot ? truncate(topHotspot.file, 28) : 'None'}`,\n        `Primary Reason: ${topHotspot ? truncate(topHotspot.primaryRisk, 28) : 'Balanced'}`,\n      ],\n    },\n    {\n      id: 'bus-factor',\n      label: 'Who Owns The Knowledge?',\n      question: 'Where is knowledge concentrated in single authors?',\n      description: 'Single-author bottlenecks and Bus Factor = 1 alerts',\n      accent: 'yellow',\n      preview: [\n        `Bus Factor = 1: ${style('bold', style(atRiskCount > 0 ? 'red' : 'green', `${atRiskCount} files at risk`))}`,\n        `Top Author:     ${overview?.knowledgeConcentration?.topCommitter || '—'}`,\n        `Avg Dominance:  ${overview?.knowledgeConcentration?.avgMaxOwnership ? `${overview.knowledgeConcentration.avgMaxOwnership}%` : '—'}`,\n      ],\n    },\n    {\n      id: 'ownership',\n      label: 'Authorship Distribution',\n      question: 'How is code ownership distributed across authors?',\n      description: 'Per-file author breakdown and contributor counts',\n      accent: 'green',\n      preview: [\n        `Contributors:   ${String(metrics.contributors ?? '—')} active authors`,\n        `Tracked Files:  ${String(metrics.files ?? '—')} files mapped`,\n        `Metric:         Dominant author & edit percentage`,\n      ],\n    },\n    {\n      id: 'churn',\n      label: 'What Changes Most?',\n      question: 'Which files undergo frequent code modifications?',\n      description: 'Change frequency rankings and volatility analysis',\n      accent: 'cyan',\n      preview: [\n        `Total Commits:  ${String(metrics.commits ?? '—')}`,\n        `Tracked Files:  ${String(metrics.files ?? '—')}`,\n        `Activity:       Ranked by revision frequency`,\n      ],\n    },\n    {\n      id: 'complexity',\n      label: 'What Is Most Complex?',\n      question: 'Which source files have highest branching & nesting?',\n      description: 'Cyclomatic branches, max depth, and code risk',\n      accent: 'magenta',\n      preview: [\n        `Language AST:   JavaScript / TypeScript`,\n        `Evaluates:      Branch density & nesting depth`,\n        `Action:         Locates refactoring targets`,\n      ],\n    },\n    {\n      id: 'log',\n      label: 'Repository History',\n      question: 'What is the full reconstructed commit history?',\n      description: 'Chronological commit graph and authorship trail',\n      accent: 'white',\n      preview: [\n        `Total Commits:  ${String(metrics.commits ?? '—')}`,\n        `Engine Mode:    Zero-dependency direct reader`,\n        `Status:         ${metrics.status ?? 'Live'}`,\n      ],\n    },\n  ];\n\n  return items.map((item, index) => ({\n    ...item,\n    index,\n    repoPath,\n  }));\n}\n\n/**\n * Render the interactive dashboard menu with structured question framing.\n */\nfunction renderDashboardMenu({ repoPath = process.cwd(), items = [], selectedIndex = 0, overview = null } = {}) {\n  const selected = items[selectedIndex] || items[0] || {};\n  const termWidth = getTerminalWidth(80);\n  const width = Math.min(termWidth - 2, 96);\n  const navWidth = Math.min(42, Math.floor(width * 0.44));\n  const detailWidth = width - navWidth - 7;\n\n  const b = BOX.rounded;\n\n  const title = style('bold', style('green', 'GIT X-RAY')) + ' ' + style('dim', '· Codebase Intelligence Dashboard');\n  const repoText = style('dim', 'repo: ') + style('bold', repoPath || process.cwd());\n\n  const navRows = items.map((item, index) => {\n    const active = index === selectedIndex;\n    const marker = active ? style('bold', style(item.accent || 'cyan', '▶')) : ' ';\n    const labelText = active\n      ? style('bold', style(item.accent || 'cyan', item.label))\n      : style('dim', item.label);\n    const row = `${marker} ${labelText}`;\n    return padRight(truncate(row, navWidth), navWidth);\n  });\n\n  const detailLines = [\n    style('bold', style(selected.accent || 'cyan', selected.label)),\n    style('bold', style('dim', `\"${selected.question}\"`)),\n    style('dim', selected.description),\n    '',\n    ...(selected.preview || []),\n    '',\n    style('cyan', '▶ Press [Enter] to inspect this analysis'),\n  ];\n\n  const maxRows = Math.max(navRows.length, detailLines.length);\n\n  const top = style('cyan', `${b.tl}${b.h.repeat(navWidth + 2)}${b.ht}${b.h.repeat(detailWidth + 2)}${b.tr}`);\n  const divider = style('cyan', `${b.vl}${b.h.repeat(navWidth + 2)}${b.x}${b.h.repeat(detailWidth + 2)}${b.vr}`);\n  const bottom = style('cyan', `${b.bl}${b.h.repeat(navWidth + 2)}${b.hb}${b.h.repeat(detailWidth + 2)}${b.br}`);\n\n  const headerRows = [\n    style('cyan', b.v) + ` ${padRight(title, width - 4)} ` + style('cyan', b.v),\n    style('cyan', b.v) + ` ${padRight(repoText, width - 4)} ` + style('cyan', b.v),\n  ];\n\n  const contentRows = [];\n  for (let i = 0; i < maxRows; i += 1) {\n    const leftText = navRows[i] || padRight('', navWidth);\n    const rightText = padRight(truncate(detailLines[i] || '', detailWidth), detailWidth);\n    contentRows.push(\n      style('cyan', b.v) + ` ${leftText} ` + style('cyan', b.v) + ` ${rightText} ` + style('cyan', b.v)\n    );\n  }\n\n  const footer = style('cyan', b.v) + ` ${padRight(style('bold', 'Navigation: [↑ / ↓] Select Question  •  [Enter] Inspect  •  [q] Quit'), width - 4)} ` + style('cyan', b.v);\n\n  return [\n    renderLogo({ showSubtitle: false }),\n    '',\n    top,\n    ...headerRows,\n    divider,\n    ...contentRows,\n    divider,\n    footer,\n    bottom,\n  ].join('\\n');\n}\n\n/**\n * Run interactive keyboard navigation loop.\n */\nfunction runInteractiveDashboard({ repoPath, commits, packedCount, diffs, options, overview, onSelect }) {\n  if (!process.stdout.isTTY) {\n    console.log(renderDashboardMenu({\n      repoPath,\n      items: buildDashboardMenu({\n        repoPath,\n        metrics: {\n          commits: commits.length,\n          files: diffs ? diffs.size : '—',\n          contributors: overview?.contributorCount ?? '—',\n          status: packedCount > 0 ? 'Partial' : 'Live'\n        },\n        overview,\n      }),\n      selectedIndex: 0,\n      overview,\n    }));\n    console.log(style('dim', '\\nNon-interactive terminal detected; use direct commands (e.g., gitxray . overview or gitxray . hotspots).'));\n    return;\n  }\n\n  const items = buildDashboardMenu({\n    repoPath,\n    metrics: {\n      commits: commits.length,\n      files: diffs ? diffs.size : '—',\n      contributors: overview?.contributorCount ?? '—',\n      status: packedCount > 0 ? 'Partial' : 'Live'\n    },\n    overview,\n  });\n\n  let selectedIndex = 0;\n  let inSubView = false;\n\n  const renderMenu = () => {\n    inSubView = false;\n    process.stdout.write('\\u001b[2J\\u001b[0;0H');\n    console.log(renderDashboardMenu({ repoPath, items, selectedIndex, overview }));\n  };\n\n  renderMenu();\n\n  const stdin = process.stdin;\n  stdin.setRawMode(true);\n  stdin.resume();\n  stdin.setEncoding('utf8');\n\n  const onKey = (key) => {\n    if (key === '\\u0003' || key.toLowerCase() === 'q') {\n      stdin.setRawMode(false);\n      stdin.pause();\n      process.stdout.write('\\u001b[2J\\u001b[0;0H');\n      process.exit(0);\n    }\n\n    if (inSubView) {\n      // Any key returns to the interactive menu\n      renderMenu();\n      return;\n    }\n\n    if (key === '\\u001b[A' || key === 'k') {\n      selectedIndex = (selectedIndex - 1 + items.length) % items.length;\n      renderMenu();\n    } else if (key === '\\u001b[B' || key === 'j') {\n      selectedIndex = (selectedIndex + 1) % items.length;\n      renderMenu();\n    } else if (key === '\\r' || key === '\\n' || key === ' ') {\n      const selected = items[selectedIndex];\n      process.stdout.write('\\u001b[2J\\u001b[0;0H');\n      if (typeof onSelect === 'function') {\n        inSubView = true;\n        onSelect(selected.id);\n        console.log(style('dim', '\\n─── Press any key to return to dashboard menu (or [q] to exit) ───'));\n      }\n    }\n  };\n\n  stdin.on('data', onKey);\n}\n\nmodule.exports = {\n  buildDashboardMenu,\n  renderDashboardMenu,\n  runInteractiveDashboard,\n};\n",
  "outputs/file-detail.js": "const {\n  style,\n  stripAnsi,\n  padRight,\n  padLeft,\n  renderBar,\n  BOX,\n  BADGES,\n} = require('../ui/core.js');\nconst { renderPanel, renderSection } = require('../ui/components.js');\n\n/**\n * Render a detailed, comprehensive forensic deep-dive view for a single file.\n *\n * @param {Object} params\n * @param {string} params.file - file path\n * @param {Object} [params.hotspot] - hotspot info { riskScore, severity, primaryRisk, churn, ownershipConcentration, recency }\n * @param {Object} [params.ownership] - ownership info { primaryAuthor, authors, distinctAuthors, lastTouched }\n * @param {Object} [params.complexity] - complexity info { score, complexity, branches, maxDepth, functions, language }\n * @param {Object} [params.churn] - churn info { touches }\n * @returns {string}\n */\nfunction renderFileDetail({ file, hotspot, ownership, complexity, churn }) {\n  const lines = [];\n  const b = BOX.rounded;\n\n  // Header Title\n  const riskScore = hotspot?.riskScore ?? 0;\n  let severity = hotspot?.severity ?? 'LOW';\n  const sevColor = severity === 'CRITICAL' ? 'red' : severity === 'HIGH' ? 'yellow' : severity === 'MEDIUM' ? 'cyan' : 'green';\n\n  lines.push(`${style('bold', style('cyan', 'File Risk Deep Dive'))}  ${style('bold', style(sevColor, `[ ${severity} RISK · ${riskScore}/100 ]`))}`);\n  lines.push(`${style('dim', 'path:')} ${style('bold', file)}`);\n  lines.push('');\n\n  // 1. Why is this file risky?\n  lines.push(style('bold', style('yellow', '⚡ Why is this file considered risky?')));\n  const reasons = [];\n  if (hotspot?.churn >= 3 || churn?.touches >= 3) {\n    const touches = hotspot?.churn || churn?.touches;\n    reasons.push(`• ${style('bold', 'High Change Frequency')}: Modified ${touches} times across recent history.`);\n  }\n  if (ownership?.primaryAuthor?.percentage >= 80 || (hotspot?.ownershipConcentration && hotspot.ownershipConcentration >= 80)) {\n    const author = ownership?.primaryAuthor?.name || 'Top Author';\n    const pct = ownership?.primaryAuthor?.percentage ?? hotspot?.ownershipConcentration;\n    reasons.push(`• ${style('bold', 'Knowledge Concentration (Bus Factor = 1)')}: ${pct}% written by ${author}. High single-person dependency.`);\n  }\n  if (complexity && (complexity.complexity === 'VERY HIGH' || complexity.complexity === 'HIGH')) {\n    reasons.push(`• ${style('bold', 'Structural Complexity')}: ${complexity.branches} branching decision points (Max Nesting Depth: ${complexity.maxDepth}).`);\n  }\n  if (hotspot?.primaryRisk && reasons.length === 0) {\n    reasons.push(`• ${style('bold', 'Primary Signal')}: ${hotspot.primaryRisk}`);\n  }\n  if (reasons.length === 0) {\n    reasons.push('• Balanced risk profile with shared authorship and manageable complexity.');\n  }\n  lines.push(reasons.join('\\n'));\n  lines.push('');\n\n  // 2. Authorship & Knowledge Ownership\n  lines.push(style('bold', style('cyan', '👤 Knowledge Ownership & Contributor Distribution')));\n  if (ownership && ownership.authors) {\n    const sortedAuthors = Object.entries(ownership.authors)\n      .sort((a, b) => b[1] - a[1]);\n    const totalTouches = sortedAuthors.reduce((sum, [, count]) => sum + count, 0);\n\n    for (const [authorName, count] of sortedAuthors) {\n      const pct = Math.round((count / totalTouches) * 100);\n      const bar = renderBar(pct, 16);\n      lines.push(`  ${padRight(authorName, 22)} ${padLeft(pct + '%', 4)}  ${bar}  ${style('dim', `(${count} edit${count === 1 ? '' : 's'})`)}`);\n    }\n  } else if (ownership?.primaryAuthor) {\n    lines.push(`  Primary Author: ${style('bold', ownership.primaryAuthor.name)} (${ownership.primaryAuthor.percentage}%)`);\n  } else {\n    lines.push(`  ${style('dim', 'Ownership details not available.')}`);\n  }\n  lines.push('');\n\n  // 3. Activity & Complexity Breakdown\n  lines.push(style('bold', style('cyan', '📊 Activity & Structural Metrics')));\n  const touchCount = churn?.touches ?? hotspot?.churn ?? '—';\n  lines.push(`  • Revision Count:        ${style('bold', String(touchCount))} commits touched this file`);\n  if (ownership?.lastTouched) {\n    const lastDate = new Date(ownership.lastTouched * 1000).toISOString().slice(0, 10);\n    lines.push(`  • Last Active:           ${style('bold', lastDate)}`);\n  }\n  if (complexity) {\n    const compColor = complexity.complexity === 'VERY HIGH' ? 'red' : complexity.complexity === 'HIGH' ? 'yellow' : 'green';\n    lines.push(`  • Complexity Score:      ${style('bold', style(compColor, `${complexity.score}/100 (${complexity.complexity})`))}`);\n    lines.push(`  • Code Structure:        ${complexity.branches} branches · ${complexity.maxDepth} nesting levels · ${complexity.functions} functions (${complexity.language})`);\n  }\n  lines.push('');\n\n  // 4. Actionable Recommendation\n  lines.push(style('bold', style('cyan', '💡 Recommended Interpretation & Next Steps')));\n  if (severity === 'CRITICAL' || severity === 'HIGH') {\n    lines.push(`  ${style('yellow', '→')} Pair on upcoming modifications or conduct an architecture review.`);\n    lines.push(`  ${style('yellow', '→')} Transfer domain knowledge to secondary team members to eliminate the single-author bottleneck.`);\n  } else {\n    lines.push(`  ${style('green', '→')} File risk is within healthy engineering tolerances.`);\n  }\n\n  return renderPanel({\n    lines,\n    borderColor: sevColor,\n  });\n}\n\nmodule.exports = {\n  renderFileDetail,\n};\n",
  "outputs/json.js": "/**\n * Format data as JSON for the --json flag.\n *\n * @param {any} data — structured data to serialize\n * @returns {string}\n */\nfunction formatJSON(data) {\n  return JSON.stringify(data, null, 2);\n}\n\nmodule.exports = { formatJSON };\n",
  "outputs/terminal.js": "const path = require('node:path');\nconst {\n  style,\n  stripAnsi,\n  visibleLength,\n  getTerminalWidth,\n  padRight,\n  padLeft,\n  padCenter,\n  truncate,\n  BOX,\n  BADGES,\n  renderBar,\n} = require('../ui/core.js');\nconst { renderLogo } = require('../ui/logo.js');\nconst {\n  renderPanel,\n  renderExecutiveCard,\n  renderTable,\n  renderSection,\n} = require('../ui/components.js');\n\n/**\n * Format a table with aligned columns for terminal output.\n * Fully ANSI-aware, supports responsive wrapping.\n *\n * @param {string[]} headers\n * @param {string[][]} rows\n * @param {{ headerStyle?: string }} options\n * @returns {string}\n */\nfunction formatTable(headers, rows, options = {}) {\n  return renderTable(headers, rows, { headerColor: options.headerStyle || 'cyan' });\n}\n\nfunction renderSummaryPanel({ title, repoPath, metrics = [], status = 'Ready' }) {\n  return renderExecutiveCard({\n    title,\n    repoPath: repoPath || process.cwd(),\n    metrics: metrics.map((m) => {\n      if (typeof m === 'string') {\n        const parts = m.split(':');\n        return { label: parts[0]?.trim() || '', value: parts[1]?.trim() || '' };\n      }\n      return m;\n    }),\n    status,\n  });\n}\n\nfunction renderDashboardSummary({ title, repoPath, metrics = [], status = 'Ready' }) {\n  return renderExecutiveCard({\n    title,\n    repoPath: repoPath || process.cwd(),\n    metrics,\n    status,\n  });\n}\n\nfunction printHeader(title, repoPath = process.cwd(), metrics = []) {\n  console.log('\\n' + renderSummaryPanel({\n    title,\n    repoPath,\n    metrics,\n    status: 'Live',\n  }));\n}\n\nfunction printWarning(message) {\n  console.log(style('yellow', `⚠  ${message}`));\n}\n\nfunction printSuccess(message) {\n  console.log(style('green', `✓  ${message}`));\n}\n\nfunction formatDate(timestamp) {\n  return new Date(timestamp * 1000).toISOString().slice(0, 10);\n}\n\nfunction formatPercent(value) {\n  return `${value.toFixed(1)}%`;\n}\n\nfunction colorPercent(value) {\n  const text = formatPercent(value);\n  if (value >= 80) return style('red', text);\n  if (value >= 50) return style('yellow', text);\n  return style('green', text);\n}\n\n/**\n * Render Executive Overview / Repository Health Report.\n * Structured around user questions: What is the state? What is wrong? What to check next?\n *\n * @param {Object} overview — from computeOverview()\n * @returns {string}\n */\nfunction renderOverviewReport(overview) {\n  const lines = [];\n\n  // 1. Clean Logo Header\n  lines.push(renderLogo({ showSubtitle: true }));\n  lines.push('');\n\n  // 2. Repository Health Summary\n  const riskColor = overview.overallRisk === 'CRITICAL' ? 'red' : overview.overallRisk === 'HIGH' ? 'yellow' : overview.overallRisk === 'MEDIUM' ? 'cyan' : 'green';\n  const riskVerdict = overview.overallRisk === 'CRITICAL'\n    ? 'CRITICAL RISK — Multiple severe fragility bottlenecks detected'\n    : overview.overallRisk === 'HIGH'\n    ? 'HIGH RISK — Notable knowledge concentration and churn hotspots'\n    : overview.overallRisk === 'MEDIUM'\n    ? 'MODERATE RISK — Minor hotspots present, overall healthy'\n    : 'HEALTHY — Codebase risks are within safe engineering margins';\n\n  const summaryBox = renderExecutiveCard({\n    title: 'Repository Health Summary',\n    repoPath: overview.repository,\n    metrics: [\n      { label: 'Risk Score', value: `${overview.riskScore} / 100 (${overview.overallRisk})`, color: riskColor },\n      { label: 'Total Commits', value: overview.commitCount },\n      { label: 'Contributors', value: overview.contributorCount },\n      { label: 'Tracked Files', value: overview.fileCount },\n    ],\n    status: overview.overallRisk === 'LOW' ? 'Healthy' : overview.overallRisk === 'MEDIUM' ? 'Moderate' : 'Risk Alert',\n  });\n  lines.push(summaryBox);\n  lines.push('');\n\n  // 3. Key Findings\n  lines.push(renderSection('Key Findings & Risk Diagnosis', '🔍'));\n  const kc = overview.knowledgeConcentration;\n  const bfa = overview.busFactorAlerts;\n  const criticalCount = overview.criticalFiles?.length || 0;\n\n  if (criticalCount > 0) {\n    lines.push(`  ${style('bold', style('red', '✗'))} ${style('bold', `${criticalCount} critical-risk file(s)`)} require attention due to high churn or extreme dominance.`);\n  } else {\n    lines.push(`  ${style('green', '✓')} No critical-risk file hotspots detected.`);\n  }\n\n  if (bfa.atRiskCount > 0) {\n    lines.push(`  ${style('bold', style('red', '✗'))} ${style('bold', `${bfa.atRiskCount} file(s)`)} have Bus Factor = 1 (${bfa.percentage}% of repository > ${bfa.threshold}% single-author ownership).`);\n  } else {\n    lines.push(`  ${style('green', '✓')} Knowledge is shared evenly across team members.`);\n  }\n\n  if (kc.topCommitterShare >= 50) {\n    lines.push(`  ${style('bold', style('yellow', '⚠'))} Top contributor ${style('bold', kc.topCommitter)} authored ${style('bold', `${kc.topCommitterShare}%`)} of all commits.`);\n  }\n\n  lines.push(`  ${style('dim', '•')} Average primary-author dominance across codebase: ${style('bold', `${kc.avgMaxOwnership}%`)}.`);\n  lines.push('');\n\n  // 4. Most At-Risk Files Table\n  lines.push(renderSection('Where Is The Risk? (Top At-Risk Files)', '⚡'));\n  if (overview.topHotspots && overview.topHotspots.length > 0) {\n    const hsHeaders = ['Risk Score', 'Severity', 'File', 'Activity Profile', 'Why Is This Risky?'];\n    const hsRows = overview.topHotspots.map((h) => {\n      const sevColor = h.severity === 'CRITICAL' ? 'red' : h.severity === 'HIGH' ? 'yellow' : h.severity === 'MEDIUM' ? 'cyan' : 'green';\n      return [\n        style('bold', `${h.riskScore}/100`),\n        style('bold', style(sevColor, h.severity)),\n        h.file,\n        `${h.churn} touches · ${h.ownershipConcentration}% dominance`,\n        h.primaryRisk,\n      ];\n    });\n    lines.push(renderTable(hsHeaders, hsRows, {\n      alignments: ['center', 'center', 'left', 'left', 'left'],\n    }));\n  } else {\n    lines.push(`  ${style('green', '✓ No high-risk files identified.')}`);\n  }\n  lines.push('');\n\n  // 5. What To Investigate Next\n  lines.push(renderSection('Recommended Next Investigation', '💡'));\n  lines.push(`  ${style('cyan', '→')} Run ${style('bold', 'Where Is The Risk?')} (or ${style('dim', 'gitxray . hotspots')}) for complete risk rankings.`);\n  lines.push(`  ${style('cyan', '→')} Run ${style('bold', 'Who Owns The Knowledge?')} (or ${style('dim', 'gitxray . bus-factor')}) to audit single-person dependencies.`);\n  lines.push(`  ${style('cyan', '→')} Run ${style('bold', 'What Is Most Complex?')} (or ${style('dim', 'gitxray . complexity')}) to find refactoring candidates.`);\n\n  return lines.join('\\n');\n}\n\n/**\n * Render Hotspots Report / \"Where Is The Risk?\"\n * @param {Array} hotspots\n * @param {string} repoPath\n * @returns {string}\n */\nfunction renderHotspotsReport(hotspots, repoPath) {\n  const lines = [];\n\n  const critical = hotspots.filter((h) => h.severity === 'CRITICAL').length;\n  const high = hotspots.filter((h) => h.severity === 'HIGH').length;\n\n  lines.push(renderDashboardSummary({\n    title: 'Where Is The Risk? (Risk Hotspots)',\n    repoPath,\n    metrics: [\n      { label: 'Files Evaluated', value: hotspots.length },\n      { label: 'Critical', value: critical, color: 'red' },\n      { label: 'High Risk', value: high, color: 'yellow' },\n    ],\n    status: critical > 0 ? 'Alert' : 'Analysis',\n  }));\n\n  lines.push('');\n  lines.push(` ${style('dim', 'What this measures:')} Combines commit frequency (40%), author concentration (35%),`);\n  lines.push(` and modification recency (25%) into an overall engineering risk score (0–100).`);\n\n  if (hotspots.length === 0) {\n    lines.push('');\n    lines.push(style('green', '✓ No risk hotspots detected across git history.'));\n    return lines.join('\\n');\n  }\n\n  lines.push(renderSection('Ranked Risk Hotspots', '⚡'));\n\n  const headers = ['Risk Score', 'Severity', 'File', 'Activity Profile', 'Why Is This Risky?'];\n  const rows = hotspots.slice(0, 15).map((h) => {\n    const sevColor = h.severity === 'CRITICAL' ? 'red' : h.severity === 'HIGH' ? 'yellow' : h.severity === 'MEDIUM' ? 'cyan' : 'green';\n    const [topAuthor] = h.topAuthor || ['Unknown'];\n    return [\n      style('bold', `${h.riskScore}/100`),\n      style('bold', style(sevColor, h.severity)),\n      h.file,\n      `${h.churn} touches · ${h.ownershipConcentration}% ${topAuthor}`,\n      h.primaryRisk,\n    ];\n  });\n\n  lines.push(renderTable(headers, rows, {\n    alignments: ['center', 'center', 'left', 'left', 'left'],\n  }));\n\n  if (hotspots.length > 15) {\n    lines.push(style('dim', `\\n  ... and ${hotspots.length - 15} more files evaluated.`));\n  }\n\n  return lines.join('\\n');\n}\n\n/**\n * Render Structural Complexity Report / \"What Is Most Complex?\"\n * @param {Array} complexities\n * @param {string} repoPath\n * @returns {string}\n */\nfunction renderComplexityReport(complexities, repoPath) {\n  const lines = [];\n  const veryHigh = complexities.filter((c) => c.complexity === 'VERY HIGH').length;\n  const high = complexities.filter((c) => c.complexity === 'HIGH').length;\n\n  lines.push(renderDashboardSummary({\n    title: 'What Is Most Complex? (Structural Complexity)',\n    repoPath,\n    metrics: [\n      { label: 'Files Analyzed', value: complexities.length },\n      { label: 'Very High', value: veryHigh, color: 'red' },\n      { label: 'High', value: high, color: 'yellow' },\n    ],\n    status: veryHigh > 0 ? 'Alert' : 'Analysis',\n  }));\n\n  lines.push('');\n  lines.push(` ${style('dim', 'What this measures:')} Evaluates cyclomatic branch density, deep nesting levels, and`);\n  lines.push(` control-flow branches to identify code that is hard to review, test, or modify safely.`);\n\n  if (complexities.length === 0) {\n    lines.push('');\n    lines.push(style('green', '✓ No source code files found for AST/cyclomatic inspection.'));\n    return lines.join('\\n');\n  }\n\n  lines.push(renderSection('Source Files Ranked by Structural Complexity', '⚙'));\n\n  const headers = ['Score', 'Complexity', 'File', 'Lang', 'Branches', 'Max Depth', 'Functions'];\n  const rows = complexities.slice(0, 15).map((c) => {\n    const lvlColor = c.complexity === 'VERY HIGH' ? 'red' : c.complexity === 'HIGH' ? 'yellow' : c.complexity === 'MEDIUM' ? 'cyan' : 'green';\n    return [\n      style('bold', `${c.score}/100`),\n      style('bold', style(lvlColor, c.complexity)),\n      c.file,\n      c.language,\n      String(c.branches),\n      String(c.maxDepth),\n      String(c.functions),\n    ];\n  });\n\n  lines.push(renderTable(headers, rows, {\n    alignments: ['center', 'center', 'left', 'center', 'center', 'center', 'center'],\n  }));\n\n  if (complexities.length > 15) {\n    lines.push(style('dim', `\\n  ... and ${complexities.length - 15} more files analyzed.`));\n  }\n\n  return lines.join('\\n');\n}\n\n/**\n * Render Knowledge / Bus-Factor Report / \"Who Owns The Knowledge?\"\n * @param {Array} busFactorData\n * @param {number} threshold\n * @param {string} repoPath\n * @returns {string}\n */\nfunction renderKnowledgeReport(busFactorData, threshold, repoPath) {\n  const atRisk = busFactorData.filter((e) => e.atRisk);\n  const safe = busFactorData.filter((e) => !e.atRisk);\n  const lines = [];\n\n  lines.push(renderDashboardSummary({\n    title: 'Who Owns The Knowledge? (Bus Factor & Ownership)',\n    repoPath,\n    metrics: [\n      { label: 'Files Analyzed', value: busFactorData.length },\n      { label: 'Bus Factor = 1', value: atRisk.length, color: atRisk.length > 0 ? 'red' : 'green' },\n      { label: 'Threshold', value: `${threshold}%` },\n    ],\n    status: atRisk.length > 0 ? 'Watchlist' : 'Healthy',\n  }));\n\n  lines.push('');\n  lines.push(` ${style('dim', 'What this measures:')} Identifies knowledge silos and single-author bottlenecks.`);\n  lines.push(` When Bus Factor is 1, losing a single contributor leaves the team without context.`);\n\n  if (atRisk.length > 0) {\n    lines.push(renderSection(`Single-Author Dominated Files (${atRisk.length} files at risk > ${threshold}%)`, '⚠'));\n    const headers = ['At-Risk File', 'Dominant Author', 'Ownership Share', 'Authors', 'Knowledge Status'];\n    const rows = atRisk.map((entry) => [\n      entry.path,\n      entry.topAuthor,\n      colorPercent(entry.topAuthorPercentage),\n      `${entry.distinctAuthors} author${entry.distinctAuthors === 1 ? '' : 's'}`,\n      entry.topAuthorPercentage >= 95 ? style('bold', style('red', 'Single Author Only')) : style('yellow', 'Heavily Dominated'),\n    ]);\n    lines.push(renderTable(headers, rows, {\n      alignments: ['left', 'left', 'center', 'center', 'left'],\n    }));\n  } else {\n    lines.push('');\n    lines.push(style('green', '✓ Bus factor looks healthy! No critical single-author bottlenecks detected.'));\n  }\n\n  if (safe.length > 0 && atRisk.length > 0) {\n    lines.push(style('dim', `\\n  ${safe.length} file(s) have shared authorship (not shown).`));\n  }\n\n  return lines.join('\\n');\n}\n\n/**\n * Render Churn Report / \"What Changes Most?\"\n * @param {Array} churnData\n * @param {number} commitCount\n * @param {string} repoPath\n * @returns {string}\n */\nfunction renderChurnReport(churnData, commitCount, repoPath) {\n  const lines = [];\n\n  lines.push(renderDashboardSummary({\n    title: 'What Changes Most? (Change Frequency)',\n    repoPath,\n    metrics: [\n      { label: 'Files Tracked', value: churnData.length },\n      { label: 'Total Commits', value: commitCount },\n    ],\n    status: 'Live',\n  }));\n\n  lines.push('');\n  lines.push(` ${style('dim', 'What this measures:')} Tracks files with the most frequent revisions over time.`);\n  lines.push(` High churn indicates volatile requirements, ongoing refactoring, or bug regression hot zones.`);\n\n  if (churnData.length === 0) {\n    lines.push('');\n    lines.push(style('green', '✓ No file modifications recorded in history.'));\n    return lines.join('\\n');\n  }\n\n  lines.push(renderSection('Files Ranked by Edit Frequency', '🔥'));\n\n  const maxTouches = churnData[0].touches;\n  const headers = ['File', 'Revisions', 'Activity Level', 'Relative Intensity'];\n  const rows = churnData.slice(0, 20).map((entry) => {\n    const pct = Math.round((entry.touches / maxTouches) * 100);\n    const level = pct >= 80 ? style('bold', style('red', 'Very High')) : pct >= 50 ? style('yellow', 'High') : pct >= 25 ? style('cyan', 'Moderate') : style('dim', 'Low');\n    const bar = renderBar(pct, 16);\n    return [\n      entry.path,\n      String(entry.touches),\n      level,\n      bar,\n    ];\n  });\n\n  lines.push(renderTable(headers, rows, {\n    alignments: ['left', 'center', 'center', 'left'],\n  }));\n\n  if (churnData.length > 20) {\n    lines.push(style('dim', `\\n  ... and ${churnData.length - 20} more files tracked.`));\n  }\n\n  return lines.join('\\n');\n}\n\nmodule.exports = {\n  style,\n  formatTable,\n  renderSummaryPanel,\n  renderDashboardSummary,\n  printHeader,\n  printWarning,\n  printSuccess,\n  formatDate,\n  formatPercent,\n  colorPercent,\n  stripAnsi,\n  renderHotspotsReport,\n  renderComplexityReport,\n  renderOverviewReport,\n  renderKnowledgeReport,\n  renderChurnReport,\n};\n",
  "cli/args.js": "const { parseArgs } = require('node:util');\n\n/**\n * Parse CLI arguments using Node's built-in util.parseArgs.\n *\n * Usage:\n *   gitxray <path> [command] [options]\n *   gitxray [command] [options]          (uses current directory)\n *\n * Commands & Aliases:\n *   overview   | health      Repository Health & Executive Overview (default)\n *   hotspots   | risk        Where Is The Risk? (Risk hotspots)\n *   bus-factor | knowledge   Who Owns The Knowledge? (Bus factor & ownership)\n *   ownership                Per-file ownership breakdown\n *   churn      | changes     What Changes Most? (Change frequency)\n *   complexity               What Is Most Complex? (Structural complexity)\n *   log        | history     Repository History (Commit timeline)\n *   interactive              Interactive forensic navigation dashboard\n *\n * Options:\n *   --json          Output as JSON\n *   --threshold N   Bus-factor threshold percentage (default: 80)\n *   -h, --help      Show help\n *\n * @returns {{ command: string, repoPath: string, options: { json: boolean, threshold: number } }}\n */\nfunction parseCLI() {\n  const COMMAND_ALIASES = {\n    health: 'overview',\n    risk: 'hotspots',\n    knowledge: 'bus-factor',\n    changes: 'churn',\n    history: 'log',\n  };\n\n  const VALID_COMMANDS = [\n    'overview',\n    'log',\n    'ownership',\n    'churn',\n    'bus-factor',\n    'hotspots',\n    'complexity',\n    'interactive',\n    ...Object.keys(COMMAND_ALIASES),\n  ];\n\n  let values;\n  let positionals;\n\n  try {\n    ({ values, positionals } = parseArgs({\n      options: {\n        json: { type: 'boolean', default: false },\n        threshold: { type: 'string', default: '80' },\n        help: { type: 'boolean', short: 'h', default: false },\n      },\n      allowPositionals: true,\n      strict: true,\n    }));\n  } catch (err) {\n    const optionName = err && err.code === 'ERR_PARSE_ARGS_UNKNOWN_OPTION' && err.optionName\n      ? err.optionName\n      : 'unknown option';\n    console.error(`Unknown option: ${optionName}`);\n    console.error('Use --help for usage information.');\n    process.exit(1);\n  }\n\n  if (values.help || positionals.length === 0) {\n    printHelp();\n    process.exit(0);\n  }\n\n  let repoPath, rawCommand;\n\n  if (positionals.length === 1) {\n    // Could be: gitxray <command> OR gitxray <path>\n    if (VALID_COMMANDS.includes(positionals[0])) {\n      rawCommand = positionals[0];\n      repoPath = process.cwd();\n    } else {\n      // Default single-path invocation launches interactive dashboard in TTY or overview in script/pipe\n      repoPath = positionals[0];\n      rawCommand = process.stdout.isTTY && !values.json ? 'interactive' : 'overview';\n    }\n  } else {\n    // gitxray <path> <command>\n    repoPath = positionals[0];\n    rawCommand = positionals[1];\n  }\n\n  if (!VALID_COMMANDS.includes(rawCommand)) {\n    console.error(`Unknown command: \"${rawCommand}\"`);\n    console.error('Available commands: overview (health), hotspots (risk), bus-factor (knowledge), churn (changes), complexity, log (history), interactive');\n    process.exit(1);\n  }\n\n  // Resolve alias if used\n  const command = COMMAND_ALIASES[rawCommand] || rawCommand;\n\n  const threshold = parseInt(values.threshold, 10);\n  if (isNaN(threshold) || threshold < 0 || threshold > 100) {\n    console.error('--threshold must be a number between 0 and 100');\n    process.exit(1);\n  }\n\n  return {\n    command,\n    repoPath,\n    options: {\n      json: values.json,\n      threshold,\n    },\n  };\n}\n\nfunction printHelp() {\n  const help = `\n╭──────────────────────────────────────────────────────────────────────╮\n│ Git X-Ray — Zero-Dependency Codebase Intelligence & Forensics       │\n├──────────────────────────────────────────────────────────────────────┤\n│ Usage:                                                               │\n│   gitxray <path> [command] [options]                                 │\n│   gitxray [command] [options]             (uses current directory)   │\n│                                                                      │\n│ Commands framed as user questions:                                   │\n│   overview   | health     Repository Health Summary (default)        │\n│   hotspots   | risk       Where Is The Risk? (Fragile files)         │\n│   bus-factor | knowledge  Who Owns The Knowledge? (Knowledge silos)  │\n│   churn      | changes    What Changes Most? (Modification churn)    │\n│   complexity              What Is Most Complex? (Structural AST)     │\n│   log        | history    Repository History (Commit timeline)       │\n│   ownership               Per-file author ownership breakdown        │\n│   interactive             Launch interactive dashboard               │\n│                                                                      │\n│ Options:                                                             │\n│   --json             Output clean JSON                               │\n│   --threshold <N>    Bus-factor risk threshold percentage (def: 80)  │\n│   -h, --help         Show this help guide                            │\n│                                                                      │\n│ Examples:                                                            │\n│   gitxray .                                                          │\n│   gitxray . risk                                                     │\n│   gitxray . knowledge --threshold 75                                 │\n│   gitxray . complexity                                               │\n╰──────────────────────────────────────────────────────────────────────╯\n`.trim();\n\n  console.log(help);\n}\n\nmodule.exports = { parseCLI };\n",
  "index.js": "const { locateGitDir, GitXRayError } = require('./git/locator.js');\r\nconst { resolveHead, getAllBranches } = require('./git/refs.js');\r\nconst { walkCommits, computeAllDiffs } = require('./git/walker.js');\r\nconst { computeChurn } = require('./analytics/churn.js');\r\nconst { computeOwnership } = require('./analytics/ownership.js');\r\nconst { computeBusFactor } = require('./analytics/bus-factor.js');\r\nconst { computeHotspots } = require('./analytics/hotspots.js');\r\nconst { computeOverview } = require('./analytics/overview.js');\r\nconst { analyzeDirectoryComplexity } = require('./analytics/complexity.js');\r\nconst { parseCLI } = require('./cli/args.js');\r\nconst { formatJSON } = require('./outputs/json.js');\r\nconst {\r\n  style,\r\n  formatTable,\r\n  renderDashboardSummary,\r\n  printHeader,\r\n  printWarning,\r\n  printSuccess,\r\n  formatDate,\r\n  colorPercent,\r\n  formatPercent,\r\n  renderHotspotsReport,\r\n  renderComplexityReport,\r\n  renderOverviewReport,\r\n  renderKnowledgeReport,\r\n  renderChurnReport,\r\n} = require('./outputs/terminal.js');\r\nconst { buildDashboardMenu, renderDashboardMenu, runInteractiveDashboard } = require('./ui/dashboard.js');\r\n\r\n/**\r\n * Main entry point — wires the full pipeline:\r\n * CLI args → .git locator → ref resolver → commit walker → tree differ → analytics → output\r\n */\r\nfunction main() {\r\n  const { command, repoPath, options } = parseCLI();\r\n\r\n  try {\r\n    // Step 1: Locate .git\r\n    const { gitDir, isBare } = locateGitDir(repoPath);\r\n\r\n    // Step 2: Resolve HEAD + get all branch tips\r\n    let head;\r\n    try {\r\n      head = resolveHead(gitDir);\r\n    } catch (err) {\r\n      if (err instanceof GitXRayError && /empty repo|broken ref/i.test(err.message)) {\r\n        if (options.json) {\r\n          console.log(formatJSON({ error: 'No commits found (empty repo or all objects are packed)' }));\r\n        } else {\r\n          printWarning('No commits found. The repo may be empty or all objects are packed.');\r\n        }\r\n        process.exit(0);\r\n      }\r\n      throw err;\r\n    }\r\n\r\n    const branches = getAllBranches(gitDir);\r\n\r\n    // Collect all unique branch tip hashes as walk starting points\r\n    const startHashes = new Set([head.hash]);\r\n    for (const branch of branches) {\r\n      startHashes.add(branch.hash);\r\n    }\r\n\r\n    // Step 3: Walk commit graph\r\n    const { commits, packedCount } = walkCommits(gitDir, [...startHashes]);\r\n\r\n    if (packedCount > 0) {\r\n      if (!options.json) {\r\n        printWarning(\r\n          `${packedCount} object(s) could not be read and were skipped. ` +\r\n            'History may be incomplete.'\r\n        );\r\n      }\r\n    }\r\n\r\n    if (commits.length === 0) {\r\n      if (options.json) {\r\n        console.log(formatJSON({ error: 'No commits found (empty repo or all objects are packed)' }));\r\n      } else {\r\n        printWarning('No commits found. The repo may be empty or all objects are packed.');\r\n      }\r\n      process.exit(0);\r\n    }\r\n\r\n    // Step 4: Dispatch to command handler\r\n    switch (command) {\r\n      case 'overview': {\r\n        const diffs = computeAllDiffs(gitDir, commits);\r\n        handleOverview(repoPath, commits, diffs, options);\r\n        break;\r\n      }\r\n      case 'interactive': {\r\n        const diffs = computeAllDiffs(gitDir, commits);\r\n        const overview = computeOverview(repoPath, commits, diffs, options.threshold);\r\n        runInteractiveDashboard({\r\n          repoPath,\r\n          commits,\r\n          packedCount,\r\n          diffs,\r\n          options,\r\n          overview,\r\n          onSelect: (selectedCommand) => {\r\n            if (selectedCommand === 'overview') handleOverview(repoPath, commits, diffs, options);\r\n            else if (selectedCommand === 'hotspots') handleHotspots(repoPath, commits, diffs, options);\r\n            else if (selectedCommand === 'bus-factor') handleBusFactor(repoPath, commits, diffs, options);\r\n            else if (selectedCommand === 'ownership') handleOwnership(repoPath, commits, diffs, options);\r\n            else if (selectedCommand === 'churn') handleChurn(repoPath, commits, diffs, options);\r\n            else if (selectedCommand === 'complexity') handleComplexity(repoPath, options);\r\n            else if (selectedCommand === 'log') handleLog(repoPath, commits, packedCount, options);\r\n          },\r\n        });\r\n        break;\r\n      }\r\n      case 'log':\r\n        handleLog(repoPath, commits, packedCount, options);\r\n        break;\r\n      case 'churn':\r\n      case 'ownership':\r\n      case 'bus-factor':\r\n      case 'hotspots': {\r\n        // These all need diffs\r\n        const diffs = computeAllDiffs(gitDir, commits);\r\n        if (command === 'churn') handleChurn(repoPath, commits, diffs, options);\r\n        else if (command === 'ownership') handleOwnership(repoPath, commits, diffs, options);\r\n        else if (command === 'bus-factor') handleBusFactor(repoPath, commits, diffs, options);\r\n        else if (command === 'hotspots') handleHotspots(repoPath, commits, diffs, options);\r\n        break;\r\n      }\r\n      case 'complexity':\r\n        handleComplexity(repoPath, options);\r\n        break;\r\n    }\r\n  } catch (err) {\r\n    if (err instanceof GitXRayError) {\r\n      if (options.json) {\r\n        console.error(formatJSON({ error: err.message }));\r\n      } else {\r\n        console.error(style('red', `Error: ${err.message}`));\r\n      }\r\n      process.exit(1);\r\n    }\r\n    // Unexpected error\r\n    console.error(style('red', `Unexpected error: ${err.message}`));\r\n    process.exit(2);\r\n  }\r\n}\r\n\r\n// ─── Command Handlers ─────────────────────────────────────────────────────────\r\n\r\nfunction handleOverview(repoPath, commits, diffs, options) {\r\n  const overview = computeOverview(repoPath, commits, diffs, options.threshold);\r\n\r\n  if (options.json) {\r\n    console.log(formatJSON(overview));\r\n    return;\r\n  }\r\n\r\n  console.log(renderOverviewReport(overview));\r\n}\r\n\r\nfunction handleLog(repoPath, commits, packedCount, options) {\r\n  if (options.json) {\r\n    const data = commits.map((c) => ({\r\n      hash: c.hash,\r\n      author: `${c.author.name} <${c.author.email}>`,\r\n      date: new Date(c.author.timestamp * 1000).toISOString(),\r\n      message: c.message.split('\\n')[0],\r\n      parents: c.parents,\r\n      isMerge: c.parents.length > 1,\r\n    }));\r\n    console.log(formatJSON({ commits: data, totalCommits: data.length, packedSkipped: packedCount }));\r\n    return;\r\n  }\r\n\r\n  console.log(\r\n    renderDashboardSummary({\r\n      title: `Commit Log (${commits.length} commits)`,\r\n      repoPath,\r\n      metrics: [\r\n        { label: 'Commits', value: commits.length },\r\n        { label: 'Packed', value: packedCount },\r\n      ],\r\n      status: 'Live',\r\n    })\r\n  );\r\n\r\n  if (commits.length <= 30) {\r\n    // Detailed view for small repos\r\n    for (const c of commits) {\r\n      const hashStr = style('yellow', c.hash.slice(0, 8));\r\n      const dateStr = style('dim', formatDate(c.author.timestamp));\r\n      const authorStr = style('green', c.author.name);\r\n      const mergeTag = c.parents.length > 1 ? style('cyan', ' [merge]') : '';\r\n      const msg = c.message.split('\\n')[0];\r\n\r\n      console.log(`${hashStr} ${dateStr} ${authorStr}${mergeTag}`);\r\n      console.log(`         ${msg}`);\r\n    }\r\n  } else {\r\n    // Table view for larger repos\r\n    const headers = ['Hash', 'Date', 'Author', 'Message'];\r\n    const rows = commits.map((c) => [\r\n      c.hash.slice(0, 8),\r\n      formatDate(c.author.timestamp),\r\n      c.author.name,\r\n      c.message.split('\\n')[0].slice(0, 60),\r\n    ]);\r\n    console.log(formatTable(headers, rows));\r\n  }\r\n\r\n  printSuccess(`${commits.length} commits analyzed`);\r\n}\r\n\r\nfunction handleChurn(repoPath, commits, diffs, options) {\r\n  const churnData = computeChurn(commits, diffs);\r\n\r\n  if (options.json) {\r\n    console.log(formatJSON({ churn: churnData, totalFiles: churnData.length }));\r\n    return;\r\n  }\r\n\r\n  console.log(renderChurnReport(churnData, commits.length, repoPath));\r\n  printSuccess(`${churnData.length} files tracked across ${commits.length} commits`);\r\n}\r\n\r\nfunction handleOwnership(repoPath, commits, diffs, options) {\r\n  const ownershipData = computeOwnership(commits, diffs);\r\n\r\n  if (options.json) {\r\n    const data = ownershipData.map((entry) => ({\r\n      ...entry,\r\n      lastTouched: new Date(entry.lastTouched * 1000).toISOString(),\r\n    }));\r\n    console.log(formatJSON({ ownership: data, totalFiles: data.length }));\r\n    return;\r\n  }\r\n\r\n  console.log(\r\n    renderDashboardSummary({\r\n      title: `Ownership Breakdown (${ownershipData.length} files)`,\r\n      repoPath,\r\n      metrics: [\r\n        { label: 'Files', value: ownershipData.length },\r\n        { label: 'Authors', value: new Set(commits.flatMap((c) => [c.author.email])).size },\r\n      ],\r\n      status: 'Healthy',\r\n    })\r\n  );\r\n\r\n  if (ownershipData.length === 0) {\r\n    printWarning('No file ownership data available.');\r\n    return;\r\n  }\r\n\r\n  const headers = ['File', 'Primary Author', 'Ownership', 'Authors', 'Last Touched'];\r\n  const rows = ownershipData.map((entry) => [\r\n    entry.path,\r\n    entry.primaryAuthor.name,\r\n    colorPercent(entry.primaryAuthor.percentage),\r\n    String(entry.distinctAuthors),\r\n    formatDate(entry.lastTouched),\r\n  ]);\r\n\r\n  console.log(formatTable(headers, rows));\r\n  printSuccess(`${ownershipData.length} files analyzed`);\r\n}\r\n\r\nfunction handleBusFactor(repoPath, commits, diffs, options) {\r\n  const ownershipData = computeOwnership(commits, diffs);\r\n  const busFactorData = computeBusFactor(ownershipData, options.threshold);\r\n  const atRisk = busFactorData.filter((e) => e.atRisk);\r\n\r\n  if (options.json) {\r\n    console.log(\r\n      formatJSON({\r\n        busFactor: busFactorData,\r\n        threshold: options.threshold,\r\n        atRiskCount: atRisk.length,\r\n        totalFiles: busFactorData.length,\r\n      })\r\n    );\r\n    return;\r\n  }\r\n\r\n  console.log(renderKnowledgeReport(busFactorData, options.threshold, repoPath));\r\n\r\n  printSuccess(\r\n    `${busFactorData.length} files analyzed, ${atRisk.length} at risk (>${options.threshold}%)`\r\n  );\r\n}\r\n\r\nfunction handleHotspots(repoPath, commits, diffs, options) {\r\n  const hotspots = computeHotspots(commits, diffs);\r\n\r\n  if (options.json) {\r\n    const data = hotspots.map((h) => ({\r\n      file: h.file,\r\n      riskScore: h.riskScore,\r\n      severity: h.severity,\r\n      churn: h.churn,\r\n      ownershipConcentration: h.ownershipConcentration,\r\n      recencyDays: Math.round(h.recency),\r\n      primaryRisk: h.primaryRisk,\r\n      topAuthor: h.topAuthor ? h.topAuthor[0] : null,\r\n    }));\r\n    console.log(formatJSON({ hotspots: data, totalFiles: data.length }));\r\n    return;\r\n  }\r\n\r\n  console.log(renderHotspotsReport(hotspots, repoPath));\r\n\r\n  // Summary stats\r\n  const critical = hotspots.filter((h) => h.severity === 'CRITICAL').length;\r\n  const high = hotspots.filter((h) => h.severity === 'HIGH').length;\r\n  const medium = hotspots.filter((h) => h.severity === 'MEDIUM').length;\r\n\r\n  if (critical > 0) {\r\n    printWarning(`⚠ ${critical} CRITICAL risk file(s) detected`);\r\n  }\r\n  if (high > 0) {\r\n    printWarning(`  ${high} HIGH risk file(s)`);\r\n  }\r\n  if (medium > 0 && critical + high === 0) {\r\n    console.log(style('dim', `  ${medium} medium risk file(s)`));\r\n  }\r\n\r\n  printSuccess(`Risk analysis complete: ${hotspots.length} files evaluated`);\r\n}\r\n\r\nfunction handleComplexity(repoPath, options) {\r\n  // Use absolute path for analysis\r\n  const absPath = require('node:path').resolve(repoPath);\r\n  const complexities = analyzeDirectoryComplexity(absPath);\r\n\r\n  if (options.json) {\r\n    const data = complexities.map((c) => ({\r\n      file: c.file,\r\n      score: c.score,\r\n      complexity: c.complexity,\r\n      branches: c.branches,\r\n      loops: c.loops,\r\n      switches: c.switches,\r\n      cases: c.cases,\r\n      catches: c.catches,\r\n      ternaries: c.ternaries,\r\n      logicalOps: c.logicalOps,\r\n      maxDepth: c.maxDepth,\r\n      functions: c.functions,\r\n      language: c.language,\r\n    }));\r\n    console.log(formatJSON({ complexities: data, totalFiles: data.length }));\r\n    return;\r\n  }\r\n\r\n  console.log(renderComplexityReport(complexities, repoPath));\r\n\r\n  // Summary stats\r\n  const veryHigh = complexities.filter((c) => c.complexity === 'VERY HIGH').length;\r\n  const high = complexities.filter((c) => c.complexity === 'HIGH').length;\r\n  const medium = complexities.filter((c) => c.complexity === 'MEDIUM').length;\r\n\r\n  if (veryHigh > 0) {\r\n    printWarning(`⚠ ${veryHigh} VERY HIGH complexity file(s)`);\r\n  }\r\n  if (high > 0) {\r\n    printWarning(`  ${high} HIGH complexity file(s)`);\r\n  }\r\n  if (medium > 0 && veryHigh + high === 0) {\r\n    console.log(style('dim', `  ${medium} medium complexity file(s)`));\r\n  }\r\n\r\n  printSuccess(`Structural analysis complete: ${complexities.length} files analyzed`);\r\n}\r\n\r\nmain();\r\n"
};

function resolveRelative(fromFile, specifier) {
  if (!specifier.startsWith('.')) {
    return specifier;
  }

  const baseDir = path.posix.dirname(fromFile || '.');
  const resolved = path.posix.normalize(path.posix.join(baseDir, specifier));
  return resolved.endsWith('.js') ? resolved : resolved + '.js';
}

function loadModule(file) {
  if (moduleCache.has(file)) {
    return moduleCache.get(file).exports;
  }

  const source = moduleSources[file];
  if (!source) {
    throw new Error('Missing bundled module: ' + file);
  }

  const module = { exports: {} };
  moduleCache.set(file, module);

  const localRequire = Object.assign((specifier) => {
    if (!specifier.startsWith('.')) {
      return require(specifier);
    }
    return loadModule(resolveRelative(file, specifier));
  }, { main: module });

  const wrapped = new Function(
    'module',
    'exports',
    'require',
    '__filename',
    '__dirname',
    source
  );

  wrapped(module, module.exports, localRequire, file, path.posix.dirname(file));
  return module.exports;
}

loadModule('index.js');
